<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>CSS Grid 布局生成器</span>
        <el-button size="small" @click="resetAll">重置</el-button>
      </div>

      <el-row :gutter="20">
        <el-col :span="16">
          <div class="preview-header">实时预览</div>
          <div class="preview-area">
            <div
              class="grid-preview"
              :style="gridStyle"
            >
              <div
                v-for="i in gridItems"
                :key="i"
                class="grid-cell"
                :style="getCellStyle(i)"
                @click="selectCell(i)"
              >
                {{ i }}
              </div>
            </div>
          </div>
        </el-col>

        <el-col :span="8">
          <div class="code-header">
            <span>CSS 代码</span>
            <el-button type="text" size="mini" @click="copyCSS">复制</el-button>
          </div>
          <el-input
            v-model="cssCode"
            type="textarea"
            :rows="16"
            readonly
            style="font-family: monospace; font-size: 12px"
          />
          <div style="margin-top: 15px" class="code-header">
            <span>HTML 代码</span>
            <el-button type="text" size="mini" @click="copyHTML">复制</el-button>
          </div>
          <el-input
            v-model="htmlCode"
            type="textarea"
            :rows="6"
            readonly
            style="font-family: monospace; font-size: 12px"
          />
        </el-col>
      </el-row>

      <el-divider>容器设置</el-divider>

      <el-row :gutter="20">
        <el-col :span="8">
          <el-form label-width="120px" size="small">
            <el-form-item label="列数">
              <el-input-number v-model="columns" :min="1" :max="6" />
            </el-form-item>
            <el-form-item label="行数">
              <el-input-number v-model="rows" :min="1" :max="6" />
            </el-form-item>
            <el-form-item label="列间距">
              <el-input-number v-model="gap" :min="0" :max="60" /> px
            </el-form-item>
            <el-form-item label="行间距">
              <el-input-number v-model="rowGap" :min="0" :max="60" /> px
            </el-form-item>
          </el-form>
        </el-col>
        <el-col :span="8">
          <el-form label-width="120px" size="small">
            <el-form-item label="justify-content">
              <el-select v-model="justifyContent">
                <el-option label="start" value="start" />
                <el-option label="center" value="center" />
                <el-option label="end" value="end" />
                <el-option label="stretch" value="stretch" />
                <el-option label="space-between" value="space-between" />
                <el-option label="space-around" value="space-around" />
                <el-option label="space-evenly" value="space-evenly" />
              </el-select>
            </el-form-item>
            <el-form-item label="align-content">
              <el-select v-model="alignContent">
                <el-option label="start" value="start" />
                <el-option label="center" value="center" />
                <el-option label="end" value="end" />
                <el-option label="stretch" value="stretch" />
                <el-option label="space-between" value="space-between" />
                <el-option label="space-around" value="space-around" />
                <el-option label="space-evenly" value="space-evenly" />
              </el-select>
            </el-form-item>
            <el-form-item label="justify-items">
              <el-select v-model="justifyItems">
                <el-option label="stretch" value="stretch" />
                <el-option label="start" value="start" />
                <el-option label="center" value="center" />
                <el-option label="end" value="end" />
              </el-select>
            </el-form-item>
            <el-form-item label="align-items">
              <el-select v-model="alignItems">
                <el-option label="stretch" value="stretch" />
                <el-option label="start" value="start" />
                <el-option label="center" value="center" />
                <el-option label="end" value="end" />
              </el-select>
            </el-form-item>
          </el-form>
        </el-col>
        <el-col :span="8">
          <el-form label-width="120px" size="small">
            <el-form-item label="列宽模板">
              <el-input v-model="columnTemplate" placeholder="例: 1fr 2fr 1fr" />
            </el-form-item>
            <el-form-item label="行高模板">
              <el-input v-model="rowTemplate" placeholder="例: 100px auto" />
            </el-form-item>
            <el-form-item label="内边距">
              <el-input-number v-model="padding" :min="0" :max="60" /> px
            </el-form-item>
          </el-form>
        </el-col>
      </el-row>

      <el-divider>子元素设置（点击预览中的格子选择）</el-divider>

      <el-row :gutter="20" v-if="selectedCell">
        <el-col :span="6">
          <el-form label-width="100px" size="small">
            <el-form-item label="所选元素">
              <el-tag>格子 #{{ selectedCell }}</el-tag>
            </el-form-item>
            <el-form-item label="grid-column">
              <el-input v-model="cellStyles[selectedCell-1].gridColumn" placeholder="例: 1 / 3 或 span 2" />
            </el-form-item>
            <el-form-item label="grid-row">
              <el-input v-model="cellStyles[selectedCell-1].gridRow" placeholder="例: 1 / 3 或 span 2" />
            </el-form-item>
          </el-form>
        </el-col>
        <el-col :span="6">
          <el-form label-width="100px" size="small">
            <el-form-item label="背景色">
              <el-color-picker v-model="cellStyles[selectedCell-1].bgColor" />
            </el-form-item>
            <el-form-item label="文字颜色">
              <el-color-picker v-model="cellStyles[selectedCell-1].textColor" />
            </el-form-item>
            <el-form-item label="justify-self">
              <el-select v-model="cellStyles[selectedCell-1].justifySelf">
                <el-option label="auto" value="auto" />
                <el-option label="stretch" value="stretch" />
                <el-option label="start" value="start" />
                <el-option label="center" value="center" />
                <el-option label="end" value="end" />
              </el-select>
            </el-form-item>
          </el-form>
        </el-col>
        <el-col :span="12">
          <el-card shadow="never" size="small">
            <div slot="header">单元格 CSS</div>
            <el-input
              :value="getSelectedCellCSS()"
              type="textarea"
              :rows="5"
              readonly
              style="font-family: monospace; font-size: 12px"
            />
            <el-button type="text" size="mini" @click="copyCellCSS">复制单元格 CSS</el-button>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'CssGridGeneratorTool',
  data() {
    return {
      columns: 3,
      rows: 2,
      gap: 10,
      rowGap: 10,
      padding: 20,
      justifyContent: 'stretch',
      alignContent: 'stretch',
      justifyItems: 'stretch',
      alignItems: 'stretch',
      columnTemplate: '1fr 1fr 1fr',
      rowTemplate: '',
      selectedCell: 1,
      cellStyles: [],
      defaultCellStyle: {
        gridColumn: '',
        gridRow: '',
        bgColor: '#409EFF',
        textColor: '#FFFFFF',
        justifySelf: 'auto',
        alignSelf: 'auto',
      }
    }
  },
  computed: {
    gridItems() {
      return this.columns * this.rows
    },
    gridStyle() {
      return {
        display: 'grid',
        gridTemplateColumns: this.columnTemplate || `repeat(${this.columns}, 1fr)`,
        gridTemplateRows: this.rowTemplate || `repeat(${this.rows}, 80px)`,
        gap: `${this.rowGap}px ${this.gap}px`,
        justifyContent: this.justifyContent,
        alignContent: this.alignContent,
        justifyItems: this.justifyItems,
        alignItems: this.alignItems,
        padding: `${this.padding}px`,
        background: '#f0f2f5',
        borderRadius: '8px',
        minHeight: '300px',
      }
    },
    cssCode() {
      let css = `.grid-container {\n`
      css += `  display: grid;\n`
      css += `  grid-template-columns: ${this.columnTemplate || `repeat(${this.columns}, 1fr)`};\n`
      css += `  grid-template-rows: ${this.rowTemplate || `repeat(${this.rows}, auto)`};\n`
      if (this.gap === this.rowGap) {
        css += `  gap: ${this.gap}px;\n`
      } else {
        css += `  column-gap: ${this.gap}px;\n`
        css += `  row-gap: ${this.rowGap}px;\n`
      }
      css += `  padding: ${this.padding}px;\n`
      css += `  justify-content: ${this.justifyContent};\n`
      css += `  align-content: ${this.alignContent};\n`
      css += `  justify-items: ${this.justifyItems};\n`
      css += `  align-items: ${this.alignItems};\n`
      css += `}\n`

      // 单元格样式
      this.cellStyles.forEach((cs, i) => {
        const extraStyles = []
        if (cs.gridColumn) extraStyles.push(`  grid-column: ${cs.gridColumn};`)
        if (cs.gridRow) extraStyles.push(`  grid-row: ${cs.gridRow};`)
        if (cs.justifySelf !== 'auto') extraStyles.push(`  justify-self: ${cs.justifySelf};`)
        if (cs.alignSelf !== 'auto') extraStyles.push(`  align-self: ${cs.alignSelf};`)
        if (extraStyles.length > 0) {
          css += `\n.grid-item:nth-child(${i + 1}) {\n${extraStyles.join('\n')}\n}\n`
        }
      })

      return css
    },
    htmlCode() {
      let html = `<div class="grid-container">\n`
      for (let i = 0; i < this.gridItems; i++) {
        html += `  <div class="grid-item">${i + 1}</div>\n`
      }
      html += `</div>`
      return html
    }
  },
  watch: {
    columns() {
      this.initCells()
    },
    rows() {
      this.initCells()
    }
  },
  mounted() {
    this.initCells()
  },
  methods: {
    initCells() {
      const total = this.columns * this.rows
      const current = this.cellStyles.length
      if (total > current) {
        for (let i = current; i < total; i++) {
          this.cellStyles.push({ ...this.defaultCellStyle, bgColor: this.getRandomColor() })
        }
      } else if (total < current) {
        this.cellStyles.splice(total)
      }
      if (this.selectedCell > total) this.selectedCell = 1
    },
    getRandomColor() {
      const colors = ['#409EFF', '#67C23A', '#E6A23C', '#F56C6C', '#909399', '#5470C6', '#91CC75', '#FAC858', '#EE6666', '#73C0DE', '#3BA272', '#FC8452', '#9A60B4']
      return colors[Math.floor(Math.random() * colors.length)]
    },
    getCellStyle(i) {
      const cs = this.cellStyles[i - 1] || this.defaultCellStyle
      return {
        background: cs.bgColor,
        color: cs.textColor,
        gridColumn: cs.gridColumn || undefined,
        gridRow: cs.gridRow || undefined,
        justifySelf: cs.justifySelf !== 'auto' ? cs.justifySelf : undefined,
        alignSelf: cs.alignSelf !== 'auto' ? cs.alignSelf : undefined,
        cursor: 'pointer',
        border: this.selectedCell === i ? '3px solid #303133' : 'none',
      }
    },
    getSelectedCellCSS() {
      const cs = this.cellStyles[this.selectedCell - 1] || this.defaultCellStyle
      let css = `.grid-item:nth-child(${this.selectedCell}) {\n`
      css += `  background: ${cs.bgColor};\n`
      css += `  color: ${cs.textColor};\n`
      if (cs.gridColumn) css += `  grid-column: ${cs.gridColumn};\n`
      if (cs.gridRow) css += `  grid-row: ${cs.gridRow};\n`
      if (cs.justifySelf !== 'auto') css += `  justify-self: ${cs.justifySelf};\n`
      if (cs.alignSelf !== 'auto') css += `  align-self: ${cs.alignSelf};\n`
      css += `}`
      return css
    },
    selectCell(i) {
      this.selectedCell = i
    },
    copyCSS() {
      navigator.clipboard.writeText(this.cssCode).then(() => this.$message.success('CSS 已复制'))
    },
    copyHTML() {
      navigator.clipboard.writeText(this.htmlCode).then(() => this.$message.success('HTML 已复制'))
    },
    copyCellCSS() {
      navigator.clipboard.writeText(this.getSelectedCellCSS()).then(() => this.$message.success('单元格 CSS 已复制'))
    },
    resetAll() {
      this.columns = 3
      this.rows = 2
      this.gap = 10
      this.rowGap = 10
      this.padding = 20
      this.justifyContent = 'stretch'
      this.alignContent = 'stretch'
      this.justifyItems = 'stretch'
      this.alignItems = 'stretch'
      this.columnTemplate = '1fr 1fr 1fr'
      this.rowTemplate = ''
      this.selectedCell = 1
      this.initCells()
    }
  }
}
</script>

