<template>
  <div class="nlp-tool">
    <el-card>
      <div slot="header">
        <span>自然语言处理</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearAll">清空</el-button>
          <el-button size="small" @click="loadExample" type="primary">加载示例</el-button>
        </el-button-group>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <el-card shadow="hover">
            <div slot="header">
              <span>文本输入</span>
            </div>
            <el-input
              type="textarea"
              :rows="10"
              v-model="inputText"
              placeholder="输入要分析的文本..."
            />
            <div class="action-buttons">
              <el-button @click="analyzeText" type="primary" :loading="loading">
                <i class="el-icon-search"></i> 分析文本
              </el-button>
            </div>
          </el-card>

          <el-card shadow="hover" style="margin-top: 20px">
            <div slot="header">
              <span>功能选择</span>
            </div>
            <el-checkbox-group v-model="selectedFunctions">
              <el-checkbox label="sentiment">情感分析</el-checkbox>
              <el-checkbox label="summary">文本摘要</el-checkbox>
              <el-checkbox label="keywords">关键词提取</el-checkbox>
              <el-checkbox label="language">语言检测</el-checkbox>
              <el-checkbox label="translate">文本翻译</el-checkbox>
            </el-checkbox-group>
            
            <div v-if="selectedFunctions.includes('translate')" style="margin-top: 20px">
              <el-form :model="translateConfig" label-width="100px">
                <el-form-item label="目标语言">
                  <el-select v-model="translateConfig.targetLang" style="width: 100%">
                    <el-option label="中文" value="zh" />
                    <el-option label="英文" value="en" />
                    <el-option label="日文" value="ja" />
                    <el-option label="韩文" value="ko" />
                    <el-option label="西班牙文" value="es" />
                    <el-option label="法文" value="fr" />
                    <el-option label="德文" value="de" />
                  </el-select>
                </el-form-item>
              </el-form>
            </div>
          </el-card>
        </el-col>

        <el-col :span="12">
          <el-card shadow="hover">
            <div slot="header">
              <span>分析结果</span>
            </div>
            
            <div v-if="loading" style="text-align: center; padding: 40px">
              <el-icon class="is-loading"><i class="el-icon-loading"></i></el-icon>
              <p style="margin-top: 10px">正在分析...</p>
            </div>
            
            <div v-else>
              <!-- 情感分析 -->
              <div v-if="results.sentiment" class="result-section">
                <h4>情感分析</h4>
                <el-progress :percentage="results.sentiment.score * 100" :color="getSentimentColor(results.sentiment.score)" />
                <div class="sentiment-label">
                  {{ results.sentiment.label }}
                </div>
              </div>
              
              <!-- 文本摘要 -->
              <div v-if="results.summary" class="result-section">
                <h4>文本摘要</h4>
                <p class="summary-text">{{ results.summary }}</p>
              </div>
              
              <!-- 关键词提取 -->
              <div v-if="results.keywords" class="result-section">
                <h4>关键词提取</h4>
                <div class="keywords">
                  <el-tag
                    v-for="(keyword, index) in results.keywords"
                    :key="index"
                    size="small"
                    :type="getKeywordType(index)"
                  >
                    {{ keyword }}
                  </el-tag>
                </div>
              </div>
              
              <!-- 语言检测 -->
              <div v-if="results.language" class="result-section">
                <h4>语言检测</h4>
                <p>{{ results.language.name }} ({{ results.language.code }})</p>
                <p>置信度: {{ (results.language.confidence * 100).toFixed(2) }}%</p>
              </div>
              
              <!-- 文本翻译 -->
              <div v-if="results.translation" class="result-section">
                <h4>文本翻译</h4>
                <p class="translation-text">{{ results.translation }}</p>
              </div>
              
              <div v-if="Object.keys(results).length === 0" style="text-align: center; padding: 40px; color: #909399">
                请输入文本并选择分析功能
              </div>
            </div>
          </el-card>

          <el-card shadow="hover" style="margin-top: 20px">
            <div slot="header">
              <span>API 配置</span>
            </div>
            <el-form :model="apiConfig" label-width="120px">
              <el-form-item label="API 类型">
                <el-select v-model="apiConfig.type" style="width: 100%">
                  <el-option label="本地分析" value="local" />
                  <el-option label="OpenAI API" value="openai" />
                  <el-option label="Google Translate" value="google" />
                </el-select>
              </el-form-item>
              <el-form-item v-if="apiConfig.type === 'openai'" label="API Key">
                <el-input v-model="apiConfig.openaiKey" type="password" placeholder="输入 OpenAI API Key" />
              </el-form-item>
              <el-form-item label="使用代理">
                <el-switch v-model="apiConfig.useProxy" />
                <span style="margin-left: 10px; font-size: 12px; color: #909399">解决跨域问题</span>
              </el-form-item>
            </el-form>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'NlpTool',
  data() {
    return {
      inputText: '',
      selectedFunctions: ['sentiment', 'summary', 'keywords', 'language'],
      translateConfig: {
        targetLang: 'zh'
      },
      apiConfig: {
        type: 'local',
        openaiKey: '',
        useProxy: false
      },
      loading: false,
      results: {}
    }
  },
  methods: {
    clearAll() {
      this.inputText = ''
      this.results = {}
    },
    loadExample() {
      this.inputText = '人工智能是计算机科学的一个分支，它试图理解智能的本质，并生产出一种新的能以人类智能相似的方式做出反应的智能机器。人工智能的研究包括机器人、语言识别、图像识别、自然语言处理和专家系统等。人工智能从诞生以来，理论和技术日益成熟，应用领域也不断扩大。'
    },
    async analyzeText() {
      if (!this.inputText.trim()) {
        this.$message.error('请输入文本')
        return
      }
      
      this.loading = true
      this.results = {}
      
      try {
        // 本地分析实现
        if (this.selectedFunctions.includes('sentiment')) {
          this.results.sentiment = this.analyzeSentiment(this.inputText)
        }
        
        if (this.selectedFunctions.includes('summary')) {
          this.results.summary = this.generateSummary(this.inputText)
        }
        
        if (this.selectedFunctions.includes('keywords')) {
          this.results.keywords = this.extractKeywords(this.inputText)
        }
        
        if (this.selectedFunctions.includes('language')) {
          this.results.language = this.detectLanguage(this.inputText)
        }
        
        if (this.selectedFunctions.includes('translate')) {
          this.results.translation = await this.translateText(this.inputText, this.translateConfig.targetLang)
        }
      } catch (error) {
        this.$message.error('分析失败: ' + error.message)
      } finally {
        this.loading = false
      }
    },
    analyzeSentiment(text) {
      // 简单的情感分析实现
      const positiveWords = ['好', '优秀', '棒', '喜欢', '高兴', '开心', '满意', '成功', '智能', '创新']
      const negativeWords = ['坏', '差', '讨厌', '难过', '悲伤', '失望', '失败', '落后', '问题', '困难']
      
      let score = 0
      positiveWords.forEach(word => {
        if (text.includes(word)) score += 0.1
      })
      negativeWords.forEach(word => {
        if (text.includes(word)) score -= 0.1
      })
      
      score = Math.max(-1, Math.min(1, score))
      let label = '中性'
      if (score > 0.2) label = '积极'
      if (score < -0.2) label = '消极'
      
      return { score, label }
    },
    generateSummary(text) {
      // 简单的摘要生成
      const sentences = text.split(/[。！？.!?]/).filter(s => s.trim())
      if (sentences.length <= 2) return text
      
      // 取前2句作为摘要
      return sentences.slice(0, 2).join('。') + '。'
    },
    extractKeywords(text) {
      // 简单的关键词提取
      const stopWords = ['的', '了', '在', '是', '我', '有', '和', '就', '不', '人', '都', '一', '一个', '上', '也', '很', '到', '说', '要', '去', '你', '会', '着', '没有', '看', '好', '自己', '这']
      
      // 分词（简单实现）
      const words = text.match(/[\u4e00-\u9fa5]+/g) || []
      const filteredWords = words.filter(word => word.length > 1 && !stopWords.includes(word))
      
      // 统计词频
      const wordCount = {}
      filteredWords.forEach(word => {
        wordCount[word] = (wordCount[word] || 0) + 1
      })
      
      // 取频率最高的5个词
      return Object.entries(wordCount)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 5)
        .map(([word]) => word)
    },
    detectLanguage(text) {
      // 简单的语言检测
      const chineseRegex = /[\u4e00-\u9fa5]/
      const hasChinese = chineseRegex.test(text)
      
      if (hasChinese) {
        return { name: '中文', code: 'zh', confidence: 0.9 }
      } else if (/^[a-zA-Z\s.,!?]+$/.test(text)) {
        return { name: '英文', code: 'en', confidence: 0.85 }
      } else {
        return { name: '未知', code: 'unknown', confidence: 0.5 }
      }
    },
    async translateText(text, targetLang) {
      // 模拟翻译
      const translations = {
        zh: '这是一段翻译文本。',
        en: 'This is a translated text.',
        ja: 'これは翻訳されたテキストです。',
        ko: '이것은 번역된 텍스트입니다.',
        es: 'Este es un texto traducido.',
        fr: 'Ceci est un texte traduit.',
        de: 'Dies ist ein übersetzter Text.'
      }
      
      // 模拟网络延迟
      await new Promise(resolve => setTimeout(resolve, 500))
      
      return translations[targetLang] || '翻译功能暂不可用'
    },
    getSentimentColor(score) {
      if (score > 0.2) return '#67C23A'
      if (score < -0.2) return '#F56C6C'
      return '#E6A23C'
    },
    getKeywordType(index) {
      const types = ['primary', 'success', 'warning', 'danger', 'info']
      return types[index % types.length]
    }
  }
}
</script>

