export default {
  name: 'EmojiPickerTool',
  data() {
    return {
      allEmojis: EMOJI_DATA,
      searchKeyword: '',
      activeCategory: 'all',
      recentEmojis: [],
      categories: [
        { key: 'all', name: '全部', emoji: '📋' },
        { key: 'smiley', name: '表情', emoji: '😀' },
        { key: 'gesture', name: '手势', emoji: '👍' },
        { key: 'heart', name: '爱心', emoji: '❤️' },
        { key: 'symbol', name: '符号', emoji: '✅' },
        { key: 'tech', name: '科技', emoji: '💻' },
        { key: 'food', name: '食物', emoji: '🍕' },
        { key: 'animal', name: '动物', emoji: '🐶' },
        { key: 'travel', name: '交通', emoji: '🚗' },
        { key: 'weather', name: '天气', emoji: '☀️' },
        { key: 'time', name: '时间', emoji: '⏰' },
      ]
    }
  },
  computed: {
    filteredEmojis() {
      let list = this.allEmojis

      if (this.activeCategory !== 'all') {
        list = list.filter(e => e.category === this.activeCategory)
      }

      if (this.searchKeyword.trim()) {
        const kw = this.searchKeyword.trim().toLowerCase()
        list = list.filter(e =>
          e.name.includes(kw) ||
          e.keywords.includes(kw)
        )
      }

      return list
    }
  },
  methods: {
    copyEmoji(emoji) {
      navigator.clipboard.writeText(emoji).then(() => {
        this.$message.success(`已复制 ${emoji}`)
        this.addRecent(emoji)
      })
    },
    addRecent(emoji) {
      this.recentEmojis = [emoji, ...this.recentEmojis.filter(e => e !== emoji)].slice(0, 12)
    }
  }
}
