<template>
  <div class="barcode-tool">
    <el-card>
      <div slot="header">
        <span>条形码/二维码生成器</span>
        <el-button style="float: right; padding: 3px 0" type="text" @click="loadExample">加载示例</el-button>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="12">
          <el-form :model="form" label-width="100px">
            <el-form-item label="码类型">
              <el-radio-group v-model="form.type">
                <el-radio-button label="qrcode">二维码</el-radio-button>
                <el-radio-button label="barcode">条形码</el-radio-button>
              </el-radio-group>
            </el-form-item>

            <el-form-item label="内容">
              <el-input
                v-model="form.content"
                type="textarea"
                :rows="4"
                placeholder="输入要编码的内容..."
              />
            </el-form-item>

            <template v-if="form.type === 'qrcode'">
              <el-form-item label="尺寸">
                <el-slider v-model="form.size" :min="100" :max="500" show-input />
              </el-form-item>
              <el-form-item label="容错级别">
                <el-radio-group v-model="form.errorCorrection">
                  <el-radio-button label="L">低</el-radio-button>
                  <el-radio-button label="M">中</el-radio-button>
                  <el-radio-button label="Q">较高</el-radio-button>
                  <el-radio-button label="H">高</el-radio-button>
                </el-radio-group>
              </el-form-item>
              <el-form-item label="前景色">
                <el-color-picker v-model="form.foreground" />
              </el-form-item>
              <el-form-item label="背景色">
                <el-color-picker v-model="form.background" />
              </el-form-item>
            </template>

            <template v-else>
              <el-form-item label="条码格式">
                <el-select v-model="form.barcodeFormat" style="width: 100%">
                  <el-option label="CODE128" value="CODE128" />
                  <el-option label="EAN13" value="EAN13" />
                  <el-option label="EAN8" value="EAN8" />
                  <el-option label="UPC" value="UPC" />
                  <el-option label="CODE39" value="CODE39" />
                  <el-option label="ITF14" value="ITF14" />
                  <el-option label="MSI" value="MSI" />
                  <el-option label="pharmacode" value="pharmacode" />
                </el-select>
              </el-form-item>
              <el-form-item label="宽度">
                <el-slider v-model="form.width" :min="100" :max="500" show-input />
              </el-form-item>
              <el-form-item label="高度">
                <el-slider v-model="form.height" :min="50" :max="200" show-input />
              </el-form-item>
              <el-form-item label="显示文字">
                <el-switch v-model="form.showText" />
              </el-form-item>
            </template>

            <el-form-item>
              <el-button type="primary" @click="generate">生成</el-button>
              <el-button @click="downloadCode">下载</el-button>
              <el-button @click="clear">清空</el-button>
            </el-form-item>
          </el-form>
        </el-col>

        <el-col :span="12">
          <div class="preview-area">
            <div class="preview-title">预览</div>
            <div class="preview-content" ref="previewContainer">
              <canvas ref="codeCanvas" v-show="generated"></canvas>
              <div v-if="!generated" class="placeholder">
                <i class="el-icon-picture-outline"></i>
                <p>生成的码将显示在这里</p>
              </div>
            </div>
            <div v-if="generated" class="code-info">
              <p>尺寸: {{ codeInfo.width }} x {{ codeInfo.height }}px</p>
              <p>内容长度: {{ form.content.length }} 字符</p>
            </div>
          </div>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
import QRCode from 'qrcode'
import JsBarcode from 'jsbarcode'

export default {
  name: 'BarcodeTool',
  data() {
    return {
      form: {
        type: 'qrcode',
        content: '',
        size: 256,
        errorCorrection: 'M',
        foreground: '#000000',
        background: '#FFFFFF',
        barcodeFormat: 'CODE128',
        width: 300,
        height: 100,
        showText: true
      },
      generated: false,
      codeInfo: {
        width: 0,
        height: 0
      }
    }
  },
  methods: {
    async generate() {
      if (!this.form.content) {
        this.$message.warning('请输入内容')
        return
      }

      const canvas = this.$refs.codeCanvas
      
      try {
        if (this.form.type === 'qrcode') {
          await QRCode.toCanvas(canvas, this.form.content, {
            width: this.form.size,
            margin: 2,
            color: {
              dark: this.form.foreground,
              light: this.form.background
            },
            errorCorrectionLevel: this.form.errorCorrection
          })
          this.codeInfo.width = this.form.size
          this.codeInfo.height = this.form.size
        } else {
          JsBarcode(canvas, this.form.content, {
            format: this.form.barcodeFormat,
            width: 2,
            height: this.form.height,
            displayValue: this.form.showText,
            fontSize: 14,
            margin: 10
          })
          this.codeInfo.width = this.form.width
          this.codeInfo.height = this.form.height + (this.form.showText ? 30 : 0)
        }
        this.generated = true
      } catch (error) {
        this.$message.error('生成失败: ' + error.message)
      }
    },
    downloadCode() {
      if (!this.generated) {
        this.$message.warning('请先生成码')
        return
      }
      const canvas = this.$refs.codeCanvas
      const link = document.createElement('a')
      link.download = `code-${Date.now()}.png`
      link.href = canvas.toDataURL('image/png')
      link.click()
    },
    clear() {
      this.form.content = ''
      this.generated = false
      const canvas = this.$refs.codeCanvas
      const ctx = canvas.getContext('2d')
      ctx.clearRect(0, 0, canvas.width, canvas.height)
    },
    loadExample() {
      if (this.form.type === 'qrcode') {
        this.form.content = 'https://www.example.com'
      } else {
        this.form.content = '123456789012'
      }
      this.generate()
    }
  }
}
</script>

<style scoped>
.barcode-tool {
  padding: 20px;
}

.preview-area {
  border: 1px solid #dcdfe6;
  border-radius: 4px;
  padding: 20px;
  min-height: 400px;
}

.preview-title {
  font-weight: bold;
  margin-bottom: 15px;
  color: #606266;
}

.preview-content {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 300px;
  background: #f5f7fa;
  border-radius: 4px;
}

.placeholder {
  text-align: center;
  color: #909399;
}

.placeholder i {
  font-size: 48px;
  margin-bottom: 10px;
}

.code-info {
  margin-top: 15px;
  padding: 10px;
  background: #f5f7fa;
  border-radius: 4px;
  font-size: 12px;
  color: #606266;
}

.code-info p {
  margin: 5px 0;
}
</style>
