<template>
  <div class="sass-compiler-tool">
    <el-card>
      <div slot="header">
        <span>Sass/Less 编译器</span>
        <el-tag v-if="!backendAvailable" type="warning" style="margin-left: 10px">需要后端服务</el-tag>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <div class="editor-header">
            <span>源代码</span>
            <el-select v-model="sourceType" size="small" style="width: 120px">
              <el-option label="Sass" value="sass" />
              <el-option label="SCSS" value="scss" />
              <el-option label="Less" value="less" />
            </el-select>
          </div>
          <el-input
            v-model="sourceCode"
            type="textarea"
            :rows="20"
            placeholder="输入 Sass/SCSS/Less 代码..."
            @input="debouncedCompile"
          />
          <div class="editor-actions">
            <el-button size="small" @click="loadExample">加载示例</el-button>
            <el-button size="small" @click="clearSource">清空</el-button>
          </div>
        </el-col>

        <el-col :span="12">
          <div class="editor-header">
            <span>CSS 输出</span>
            <el-button-group>
              <el-button size="small" @click="copyResult">复制</el-button>
              <el-button size="small" @click="downloadResult">下载</el-button>
            </el-button-group>
          </div>
          <el-input
            v-model="compiledCss"
            type="textarea"
            :rows="20"
            readonly
            placeholder="编译后的 CSS 将显示在这里..."
          />
          <div class="editor-info" v-if="compiledCss">
            <el-tag size="small">{{ compiledCss.length }} 字符</el-tag>
            <el-tag size="small" style="margin-left: 10px">{{ lineCount }} 行</el-tag>
          </div>
        </el-col>
      </el-row>

      <el-divider>编译选项</el-divider>

      <el-form label-width="100px" :inline="true">
        <el-form-item label="输出格式">
          <el-select v-model="outputStyle" @change="compile">
            <el-option label="展开 (expanded)" value="expanded" />
            <el-option label="压缩 (compressed)" value="compressed" />
            <el-option label="嵌套 (nested)" value="nested" />
            <el-option label="紧凑 (compact)" value="compact" />
          </el-select>
        </el-form-item>
        <el-form-item label="源映射">
          <el-switch v-model="sourceMap" @change="compile" />
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="compile" :loading="compiling">编译</el-button>
        </el-form-item>
      </el-form>

      <el-divider v-if="error">错误信息</el-divider>

      <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" />
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'SassCompilerTool',
  data() {
    return {
      backendAvailable: false,
      sourceType: 'scss',
      sourceCode: '',
      compiledCss: '',
      outputStyle: 'expanded',
      sourceMap: false,
      compiling: false,
      error: '',
      compileTimer: null
    }
  },
  computed: {
    lineCount() {
      return this.compiledCss.split('\n').length
    }
  },
  async mounted() {
    await this.checkBackend()
    this.loadSassJs()
  },
  methods: {
    async checkBackend() {
      try {
        const response = await fetch('/api/ping', { 
          method: 'GET',
          signal: AbortSignal.timeout(3000)
        })
        this.backendAvailable = response.ok
      } catch (e) {
        this.backendAvailable = false
      }
    },
    loadSassJs() {
      if (window.Sass) return

      const script = document.createElement('script')
      script.src = 'https://cdnjs.cloudflare.com/ajax/libs/sass.js/0.11.1/sass.sync.min.js'
      document.head.appendChild(script)
    },
    debouncedCompile() {
      if (this.compileTimer) {
        clearTimeout(this.compileTimer)
      }
      this.compileTimer = setTimeout(() => {
        this.compile()
      }, 500)
    },
    async compile() {
      if (!this.sourceCode.trim()) {
        this.compiledCss = ''
        this.error = ''
        return
      }

      this.compiling = true
      this.error = ''

      try {
        if (this.sourceType === 'less') {
          await this.compileLess()
        } else {
          await this.compileSass()
        }
      } catch (error) {
        this.error = error.message || '编译失败'
        this.compiledCss = ''
      } finally {
        this.compiling = false
      }
    },
    async compileSass() {
      if (!window.Sass) {
        this.error = 'Sass.js 正在加载中，请稍后重试'
        return
      }

      return new Promise((resolve, reject) => {
        const options = {
          style: window.Sass.style[this.outputStyle] || window.Sass.style.expanded
        }

        window.Sass.compile(this.sourceCode, options, (result) => {
          if (result.status === 0) {
            this.compiledCss = result.text
            resolve()
          } else {
            reject(new Error(result.message || 'Sass 编译错误'))
          }
        })
      })
    },
    async compileLess() {
      if (!window.less) {
        await this.loadLessJs()
      }

      if (!window.less) {
        this.error = 'Less.js 正在加载中，请稍后重试'
        return
      }

      return new Promise((resolve, reject) => {
        window.less.render(this.sourceCode, {
          compress: this.outputStyle === 'compressed'
        }, (error, output) => {
          if (error) {
            reject(new Error(error.message || 'Less 编译错误'))
          } else {
            this.compiledCss = output.css
            resolve()
          }
        })
      })
    },
    loadLessJs() {
      return new Promise((resolve) => {
        if (window.less) {
          resolve()
          return
        }
        const script = document.createElement('script')
        script.src = 'https://cdnjs.cloudflare.com/ajax/libs/less.js/4.2.0/less.min.js'
        script.onload = resolve
        document.head.appendChild(script)
      })
    },
    copyResult() {
      if (!this.compiledCss) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.compiledCss).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    downloadResult() {
      if (!this.compiledCss) {
        this.$message.warning('没有可下载的内容')
        return
      }
      const blob = new Blob([this.compiledCss], { type: 'text/css' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = 'style.css'
      link.click()
      URL.revokeObjectURL(url)
    },
    loadExample() {
      if (this.sourceType === 'less') {
        this.sourceCode = `// Less Example
@primary-color: #409EFF;
@border-radius: 4px;

.button {
  display: inline-block;
  padding: 10px 20px;
  background-color: @primary-color;
  border-radius: @border-radius;
  color: white;
  
  &:hover {
    background-color: darken(@primary-color, 10%);
  }
  
  &.large {
    padding: 15px 30px;
    font-size: 18px;
  }
}

.container {
  .button {
    margin: 10px;
  }
}`
      } else if (this.sourceType === 'sass') {
        this.sourceCode = `// Sass Example
$primary-color: #409EFF
$border-radius: 4px

.button
  display: inline-block
  padding: 10px 20px
  background-color: $primary-color
  border-radius: $border-radius
  color: white
  
  &:hover
    background-color: darken($primary-color, 10%)
  
  &.large
    padding: 15px 30px
    font-size: 18px

.container
  .button
    margin: 10px`
      } else {
        this.sourceCode = `// SCSS Example
$primary-color: #409EFF;
$border-radius: 4px;

.button {
  display: inline-block;
  padding: 10px 20px;
  background-color: $primary-color;
  border-radius: $border-radius;
  color: white;
  
  &:hover {
    background-color: darken($primary-color, 10%);
  }
  
  &.large {
    padding: 15px 30px;
    font-size: 18px;
  }
}

.container {
  .button {
    margin: 10px;
  }
}`
      }
      this.compile()
    },
    clearSource() {
      this.sourceCode = ''
      this.compiledCss = ''
      this.error = ''
    }
  }
}
</script>

<style scoped>
.sass-compiler-tool {
  padding: 20px;
}

.editor-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
  font-weight: bold;
}

.editor-actions {
  margin-top: 10px;
  text-align: right;
}

.editor-info {
  margin-top: 10px;
  text-align: right;
}
</style>
