<template>
  <div class="escape-tool">
    <el-card>
      <div slot="header">
        <span>转义序列工具</span>
      </div>

      <el-row :gutter="20">
        <el-col :span="11">
          <div class="section-header">
            <span>原始文本</span>
            <el-button type="text" @click="copyOriginal">复制</el-button>
          </div>
          <el-input
            v-model="originalText"
            type="textarea"
            :rows="10"
            placeholder="输入原始文本..."
          />
        </el-col>

        <el-col :span="2" class="convert-buttons">
          <el-button type="primary" icon="el-icon-right" @click="escape" title="转义"></el-button>
          <el-button type="primary" icon="el-icon-back" @click="unescape" title="反转义"></el-button>
        </el-col>

        <el-col :span="11">
          <div class="section-header">
            <span>转义结果</span>
            <el-button type="text" @click="copyEscaped">复制</el-button>
          </div>
          <el-input
            v-model="escapedText"
            type="textarea"
            :rows="10"
            placeholder="转义后的文本..."
          />
        </el-col>
      </el-row>

      <el-divider>转义选项</el-divider>

      <el-form label-width="100px">
        <el-row :gutter="20">
          <el-col :span="8">
            <el-form-item label="转义类型">
              <el-select v-model="escapeType" style="width: 100%">
                <el-option label="JSON/JavaScript" value="json" />
                <el-option label="HTML" value="html" />
                <el-option label="URL" value="url" />
                <el-option label="Java" value="java" />
                <el-option label="Python" value="python" />
                <el-option label="C/C++" value="c" />
                <el-option label="SQL" value="sql" />
                <el-option label="正则表达式" value="regex" />
              </el-select>
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="编码">
              <el-select v-model="encoding" style="width: 100%">
                <el-option label="UTF-8" value="utf8" />
                <el-option label="Unicode" value="unicode" />
                <el-option label="HTML实体" value="htmlEntity" />
              </el-select>
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="选项">
              <el-checkbox v-model="escapeQuotes">转义引号</el-checkbox>
              <el-checkbox v-model="escapeNewlines">转义换行</el-checkbox>
            </el-form-item>
          </el-col>
        </el-row>
      </el-form>

      <el-divider>常用转义字符</el-divider>

      <el-table :data="escapeChars" border size="small">
        <el-table-column prop="char" label="字符" width="100" />
        <el-table-column prop="name" label="名称" />
        <el-table-column prop="escape" label="转义序列" width="150" />
        <el-table-column prop="unicode" label="Unicode" width="150" />
      </el-table>

      <div class="action-buttons">
        <el-button type="primary" @click="escape">转义</el-button>
        <el-button type="primary" @click="unescape">反转义</el-button>
        <el-button @click="loadExample">加载示例</el-button>
        <el-button @click="clear">清空</el-button>
      </div>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'EscapeTool',
  data() {
    return {
      originalText: '',
      escapedText: '',
      escapeType: 'json',
      encoding: 'utf8',
      escapeQuotes: true,
      escapeNewlines: true,
      escapeChars: [
        { char: '\\', name: '反斜杠', escape: '\\\\', unicode: 'U+005C' },
        { char: '\'', name: '单引号', escape: '\\\'', unicode: 'U+0027' },
        { char: '"', name: '双引号', escape: '\\"', unicode: 'U+0022' },
        { char: '\n', name: '换行', escape: '\\n', unicode: 'U+000A' },
        { char: '\r', name: '回车', escape: '\\r', unicode: 'U+000D' },
        { char: '\t', name: '制表符', escape: '\\t', unicode: 'U+0009' },
        { char: '\b', name: '退格', escape: '\\b', unicode: 'U+0008' },
        { char: '\f', name: '换页', escape: '\\f', unicode: 'U+000C' },
        { char: '\0', name: '空字符', escape: '\\0', unicode: 'U+0000' }
      ]
    }
  },
  methods: {
    escape() {
      if (!this.originalText) {
        this.$message.warning('请输入文本')
        return
      }

      let result = this.originalText

      switch (this.escapeType) {
        case 'json':
          result = this.escapeJson(result)
          break
        case 'html':
          result = this.escapeHtml(result)
          break
        case 'url':
          result = encodeURIComponent(result)
          break
        case 'java':
          result = this.escapeJava(result)
          break
        case 'python':
          result = this.escapePython(result)
          break
        case 'c':
          result = this.escapeC(result)
          break
        case 'sql':
          result = result.replace(/'/g, "''")
          break
        case 'regex':
          result = result.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
          break
      }

      this.escapedText = result
      this.$message.success('转义完成')
    },
    unescape() {
      if (!this.escapedText) {
        this.$message.warning('请输入转义文本')
        return
      }

      let result = this.escapedText

      try {
        switch (this.escapeType) {
          case 'json':
            result = this.unescapeJson(result)
            break
          case 'html':
            result = this.unescapeHtml(result)
            break
          case 'url':
            result = decodeURIComponent(result)
            break
          case 'java':
          case 'python':
          case 'c':
            result = this.unescapeString(result)
            break
          case 'sql':
            result = result.replace(/''/g, "'")
            break
          case 'regex':
            result = result.replace(/\\([.*+?^${}()|[\]\\])/g, '$1')
            break
        }

        this.originalText = result
        this.$message.success('反转义完成')
      } catch (e) {
        this.$message.error('反转义失败: ' + e.message)
      }
    },
    escapeJson(str) {
      return JSON.stringify(str).slice(1, -1)
    },
    unescapeJson(str) {
      return JSON.parse('"' + str + '"')
    },
    escapeHtml(str) {
      const htmlEntities = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;'
      }
      return str.replace(/[&<>"']/g, char => htmlEntities[char])
    },
    unescapeHtml(str) {
      const htmlEntities = {
        '&amp;': '&',
        '&lt;': '<',
        '&gt;': '>',
        '&quot;': '"',
        '&#39;': "'",
        '&apos;': "'"
      }
      return str.replace(/&(amp|lt|gt|quot|#39|apos);/g, entity => htmlEntities[entity])
    },
    escapeJava(str) {
      return str
        .replace(/\\/g, '\\\\')
        .replace(/"/g, '\\"')
        .replace(/\n/g, '\\n')
        .replace(/\r/g, '\\r')
        .replace(/\t/g, '\\t')
    },
    escapePython(str) {
      return this.escapeJava(str)
    },
    escapeC(str) {
      return this.escapeJava(str)
    },
    unescapeString(str) {
      return str
        .replace(/\\n/g, '\n')
        .replace(/\\r/g, '\r')
        .replace(/\\t/g, '\t')
        .replace(/\\"/g, '"')
        .replace(/\\'/g, "'")
        .replace(/\\\\/g, '\\')
    },
    copyOriginal() {
      if (!this.originalText) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.originalText).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    copyEscaped() {
      if (!this.escapedText) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.escapedText).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    loadExample() {
      this.originalText = 'Hello "World"\n这是一个测试\t包含特殊字符\\和引号\''
    },
    clear() {
      this.originalText = ''
      this.escapedText = ''
    }
  }
}
</script>

<style scoped>
.escape-tool {
  padding: 20px;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}

.convert-buttons {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 10px;
}

.action-buttons {
  text-align: center;
  margin-top: 20px;
}
</style>
