<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>随机数生成</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearAll">清空</el-button>
        </el-button-group>
      </div>
      
      <el-tabs v-model="activeTab">
        <el-tab-pane label="随机数" name="number">
          <div class="tab-content">
            <el-form :model="numberForm" label-width="100px" size="small">
              <el-form-item label="最小值">
                <el-input-number v-model="numberForm.min" :min="0" />
              </el-form-item>
              <el-form-item label="最大值">
                <el-input-number v-model="numberForm.max" :min="0" />
              </el-form-item>
              <el-form-item label="数量">
                <el-input-number v-model="numberForm.count" :min="1" :max="1000" />
              </el-form-item>
              <el-form-item label="是否重复">
                <el-switch v-model="numberForm.allowRepeat" />
              </el-form-item>
              <el-form-item>
                <el-button type="primary" @click="generateNumbers">生成</el-button>
              </el-form-item>
            </el-form>
            
            <el-divider>结果</el-divider>
            
            <el-input
              v-model="numberResult"
              type="textarea"
              :rows="10"
              readonly
            />
            <div style="margin-top: 10px">
              <el-button type="text" size="small" @click="copyNumbers">复制</el-button>
              <el-button type="text" size="small" @click="downloadNumbers">下载</el-button>
            </div>
          </div>
        </el-tab-pane>
        
        <el-tab-pane label="随机字符串" name="string">
          <div class="tab-content">
            <el-form :model="stringForm" label-width="100px" size="small">
              <el-form-item label="长度">
                <el-input-number v-model="stringForm.length" :min="1" :max="1000" />
              </el-form-item>
              <el-form-item label="数量">
                <el-input-number v-model="stringForm.count" :min="1" :max="100" />
              </el-form-item>
              <el-form-item label="字符集">
                <el-checkbox-group v-model="stringForm.charSet">
                  <el-checkbox label="大写字母">A-Z</el-checkbox>
                  <el-checkbox label="小写字母">a-z</el-checkbox>
                  <el-checkbox label="数字">0-9</el-checkbox>
                  <el-checkbox label="特殊字符">!@#$%^&*</el-checkbox>
                </el-checkbox-group>
              </el-form-item>
              <el-form-item label="自定义字符">
                <el-input v-model="stringForm.customChars" placeholder="输入自定义字符" />
              </el-form-item>
              <el-form-item>
                <el-button type="primary" @click="generateStrings">生成</el-button>
              </el-form-item>
            </el-form>
            
            <el-divider>结果</el-divider>
            
            <el-input
              v-model="stringResult"
              type="textarea"
              :rows="10"
              readonly
            />
            <div style="margin-top: 10px">
              <el-button type="text" size="small" @click="copyStrings">复制</el-button>
              <el-button type="text" size="small" @click="downloadStrings">下载</el-button>
            </div>
          </div>
        </el-tab-pane>
        
        <el-tab-pane label="随机密码" name="password">
          <div class="tab-content">
            <el-form :model="passwordForm" label-width="100px" size="small">
              <el-form-item label="长度">
                <el-input-number v-model="passwordForm.length" :min="8" :max="64" />
              </el-form-item>
              <el-form-item label="数量">
                <el-input-number v-model="passwordForm.count" :min="1" :max="50" />
              </el-form-item>
              <el-form-item label="字符集">
                <el-checkbox-group v-model="passwordForm.charSet">
                  <el-checkbox label="大写字母">A-Z</el-checkbox>
                  <el-checkbox label="小写字母">a-z</el-checkbox>
                  <el-checkbox label="数字">0-9</el-checkbox>
                  <el-checkbox label="特殊字符">!@#$%^&*</el-checkbox>
                </el-checkbox-group>
              </el-form-item>
              <el-form-item label="强度">
                <el-progress :percentage="passwordStrength" :color="strengthColor" />
              </el-form-item>
              <el-form-item>
                <el-button type="primary" @click="generatePasswords">生成</el-button>
              </el-form-item>
            </el-form>
            
            <el-divider>结果</el-divider>
            
            <el-input
              v-model="passwordResult"
              type="textarea"
              :rows="10"
              readonly
            />
            <div style="margin-top: 10px">
              <el-button type="text" size="small" @click="copyPasswords">复制</el-button>
              <el-button type="text" size="small" @click="downloadPasswords">下载</el-button>
            </div>
          </div>
        </el-tab-pane>
        
        <el-tab-pane label="随机UUID" name="uuid">
          <div class="tab-content">
            <el-form :model="uuidForm" label-width="100px" size="small">
              <el-form-item label="数量">
                <el-input-number v-model="uuidForm.count" :min="1" :max="100" />
              </el-form-item>
              <el-form-item label="格式">
                <el-select v-model="uuidForm.format">
                  <el-option label="标准格式" value="standard" />
                  <el-option label="无连字符" value="no-dash" />
                  <el-option label="大写" value="uppercase" />
                </el-select>
              </el-form-item>
              <el-form-item>
                <el-button type="primary" @click="generateUuids">生成</el-button>
              </el-form-item>
            </el-form>
            
            <el-divider>结果</el-divider>
            
            <el-input
              v-model="uuidResult"
              type="textarea"
              :rows="10"
              readonly
            />
            <div style="margin-top: 10px">
              <el-button type="text" size="small" @click="copyUuids">复制</el-button>
              <el-button type="text" size="small" @click="downloadUuids">下载</el-button>
            </div>
          </div>
        </el-tab-pane>
        
        <el-tab-pane label="随机颜色" name="color">
          <div class="tab-content">
            <el-form :model="colorForm" label-width="100px" size="small">
              <el-form-item label="数量">
                <el-input-number v-model="colorForm.count" :min="1" :max="100" />
              </el-form-item>
              <el-form-item label="格式">
                <el-select v-model="colorForm.format">
                  <el-option label="HEX" value="hex" />
                  <el-option label="RGB" value="rgb" />
                  <el-option label="HSL" value="hsl" />
                </el-select>
              </el-form-item>
              <el-form-item>
                <el-button type="primary" @click="generateColors">生成</el-button>
              </el-form-item>
            </el-form>
            
            <el-divider>结果</el-divider>
            
            <el-row :gutter="10">
              <el-col :span="8" v-for="(color, index) in colors" :key="index">
                <el-card shadow="hover" class="color-card">
                  <div class="color-preview" :style="{ backgroundColor: color.value }"></div>
                  <div class="color-value">{{ color.value }}</div>
                </el-card>
              </el-col>
            </el-row>
            <div style="margin-top: 10px">
              <el-button type="text" size="small" @click="copyColors">复制</el-button>
              <el-button type="text" size="small" @click="downloadColors">下载</el-button>
            </div>
          </div>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'RandomTool',
  data() {
    return {
      activeTab: 'number',
      numberForm: {
        min: 0,
        max: 100,
        count: 10,
        allowRepeat: false
      },
      numberResult: '',
      stringForm: {
        length: 10,
        count: 10,
        charSet: ['大写字母', '小写字母', '数字'],
        customChars: ''
      },
      stringResult: '',
      passwordForm: {
        length: 16,
        count: 10,
        charSet: ['大写字母', '小写字母', '数字', '特殊字符']
      },
      passwordResult: '',
      passwordStrength: 0,
      strengthColor: '#f56c6c',
      uuidForm: {
        count: 10,
        format: 'standard'
      },
      uuidResult: '',
      colorForm: {
        count: 10,
        format: 'hex'
      },
      colors: []
    }
  },
  methods: {
    generateNumbers() {
      const { min, max, count, allowRepeat } = this.numberForm
      const numbers = []
      
      if (allowRepeat) {
        for (let i = 0; i < count; i++) {
          numbers.push(Math.floor(Math.random() * (max - min + 1)) + min)
        }
      } else {
        const range = max - min + 1
        if (count > range) {
          this.$message.warning('数量超过范围，无法生成不重复的随机数')
          return
        }
        
        const pool = Array.from({ length: range }, (_, i) => min + i)
        for (let i = 0; i < count; i++) {
          const index = Math.floor(Math.random() * pool.length)
          numbers.push(pool.splice(index, 1)[0])
        }
      }
      
      this.numberResult = numbers.join('\n')
      this.$message.success('生成成功')
    },
    generateStrings() {
      const { length, count, charSet, customChars } = this.stringForm
      let chars = ''
      
      if (charSet.includes('大写字母')) chars += 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
      if (charSet.includes('小写字母')) chars += 'abcdefghijklmnopqrstuvwxyz'
      if (charSet.includes('数字')) chars += '0123456789'
      if (charSet.includes('特殊字符')) chars += '!@#$%^&*'
      chars += customChars
      
      if (chars.length === 0) {
        this.$message.warning('请选择至少一种字符集')
        return
      }
      
      const strings = []
      for (let i = 0; i < count; i++) {
        let str = ''
        for (let j = 0; j < length; j++) {
          str += chars.charAt(Math.floor(Math.random() * chars.length))
        }
        strings.push(str)
      }
      
      this.stringResult = strings.join('\n')
      this.$message.success('生成成功')
    },
    generatePasswords() {
      const { length, count, charSet } = this.passwordForm
      let chars = ''
      
      if (charSet.includes('大写字母')) chars += 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
      if (charSet.includes('小写字母')) chars += 'abcdefghijklmnopqrstuvwxyz'
      if (charSet.includes('数字')) chars += '0123456789'
      if (charSet.includes('特殊字符')) chars += '!@#$%^&*'
      
      if (chars.length === 0) {
        this.$message.warning('请选择至少一种字符集')
        return
      }
      
      const passwords = []
      for (let i = 0; i < count; i++) {
        let password = ''
        for (let j = 0; j < length; j++) {
          password += chars.charAt(Math.floor(Math.random() * chars.length))
        }
        passwords.push(password)
      }
      
      this.passwordResult = passwords.join('\n')
      this.calculatePasswordStrength(passwords[0])
      this.$message.success('生成成功')
    },
    calculatePasswordStrength(password) {
      let strength = 0
      
      if (password.length >= 8) strength += 20
      if (password.length >= 12) strength += 20
      if (password.length >= 16) strength += 10
      
      if (/[a-z]/.test(password)) strength += 10
      if (/[A-Z]/.test(password)) strength += 10
      if (/[0-9]/.test(password)) strength += 10
      if (/[^a-zA-Z0-9]/.test(password)) strength += 20
      
      this.passwordStrength = Math.min(strength, 100)
      
      if (this.passwordStrength < 40) {
        this.strengthColor = '#f56c6c'
      } else if (this.passwordStrength < 70) {
        this.strengthColor = '#e6a23c'
      } else {
        this.strengthColor = '#67c23a'
      }
    },
    generateUuids() {
      const { count, format } = this.uuidForm
      const uuids = []
      
      for (let i = 0; i < count; i++) {
        let uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
          const r = Math.random() * 16 | 0
          const v = c === 'x' ? r : (r & 0x3 | 0x8)
          return v.toString(16)
        })
        
        if (format === 'no-dash') {
          uuid = uuid.replace(/-/g, '')
        } else if (format === 'uppercase') {
          uuid = uuid.toUpperCase()
        }
        
        uuids.push(uuid)
      }
      
      this.uuidResult = uuids.join('\n')
      this.$message.success('生成成功')
    },
    generateColors() {
      const { count, format } = this.colorForm
      const colors = []
      
      for (let i = 0; i < count; i++) {
        const r = Math.floor(Math.random() * 256)
        const g = Math.floor(Math.random() * 256)
        const b = Math.floor(Math.random() * 256)
        
        let value = ''
        if (format === 'hex') {
          value = `#${r.toString(16).padStart(2, '0')}${g.toString(16).padStart(2, '0')}${b.toString(16).padStart(2, '0')}`
        } else if (format === 'rgb') {
          value = `rgb(${r}, ${g}, ${b})`
        } else if (format === 'hsl') {
          const h = Math.floor(Math.random() * 360)
          const s = Math.floor(Math.random() * 100)
          const l = Math.floor(Math.random() * 100)
          value = `hsl(${h}, ${s}%, ${l}%)`
        }
        
        colors.push({ value })
      }
      
      this.colors = colors
      this.$message.success('生成成功')
    },
    copyNumbers() {
      navigator.clipboard.writeText(this.numberResult).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    downloadNumbers() {
      const blob = new Blob([this.numberResult], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = 'numbers.txt'
      a.click()
      URL.revokeObjectURL(url)
      this.$message.success('下载成功')
    },
    copyStrings() {
      navigator.clipboard.writeText(this.stringResult).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    downloadStrings() {
      const blob = new Blob([this.stringResult], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = 'strings.txt'
      a.click()
      URL.revokeObjectURL(url)
      this.$message.success('下载成功')
    },
    copyPasswords() {
      navigator.clipboard.writeText(this.passwordResult).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    downloadPasswords() {
      const blob = new Blob([this.passwordResult], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = 'passwords.txt'
      a.click()
      URL.revokeObjectURL(url)
      this.$message.success('下载成功')
    },
    copyUuids() {
      navigator.clipboard.writeText(this.uuidResult).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    downloadUuids() {
      const blob = new Blob([this.uuidResult], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = 'uuids.txt'
      a.click()
      URL.revokeObjectURL(url)
      this.$message.success('下载成功')
    },
    copyColors() {
      const text = this.colors.map(c => c.value).join('\n')
      navigator.clipboard.writeText(text).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    downloadColors() {
      const text = this.colors.map(c => c.value).join('\n')
      const blob = new Blob([text], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = 'colors.txt'
      a.click()
      URL.revokeObjectURL(url)
      this.$message.success('下载成功')
    },
    clearAll() {
      this.numberResult = ''
      this.stringResult = ''
      this.passwordResult = ''
      this.uuidResult = ''
      this.colors = []
      this.passwordStrength = 0
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .tool-card {
    .header-actions {
      float: right;
    }
  }

  .tab-content {
    padding: 20px 0;
  }

  .color-card {
    margin-bottom: 10px;
    
    .color-preview {
      height: 60px;
      border-radius: 4px;
      margin-bottom: 10px;
    }
    
    .color-value {
      text-align: center;
      font-family: 'Monaco', 'Menlo', 'Consolas', monospace;
      font-size: 12px;
    }
  }
}
</style>
