// 所有命令数据汇总 - 超过5000个命令

import linuxBasicCommands from './linux-basic.js'
import linuxFileCommands from './linux-file.js'
import linuxNetworkCommands from './linux-network.js'
import linuxSystemCommands from './linux-system.js'
import linuxTextCommands from './linux-text.js'
import linuxDiskCommands from './linux-disk.js'
import linuxProcessCommands from './linux-process.js'
import linuxPermCommands from './linux-perm.js'
import linuxUserCommands from './linux-user.js'
import linuxPackageCommands from './linux-package.js'
import linuxArchiveCommands from './linux-archive.js'
import linuxPerfCommands from './linux-perf.js'
import gitCommands from './git.js'
import dockerCommands from './docker.js'
import k8sCommands from './k8s.js'
import vimCommands from './vim.js'
import terminalCommands from './terminal.js'
import curlCommands from './curl.js'
import systemdCommands from './systemd.js'
import sshCommands from './ssh.js'
import awkSedCommands from './awk-sed.js'
import elasticsearchCommands from './elasticsearch.js'
import mongodbCommands from './mongodb.js'
import postgresqlCommands from './postgresql.js'
import npmCommands from './npm.js'
import nginxCommands from './nginx.js'
import gradleCommands from './gradle.js'
import mavenCommands from './maven.js'
import redisCommands from './redis.js'
import mysqlCommands from './mysql.js'
import pythonCommands from './python.js'
import goCommands from './go.js'
import javaCommands from './java.js'
import kafkaCommands from './kafka.js'

// 合并所有命令
const allCommands = [
  ...linuxBasicCommands,
  ...linuxFileCommands,
  ...linuxNetworkCommands,
  ...linuxSystemCommands,
  ...linuxTextCommands,
  ...linuxDiskCommands,
  ...linuxProcessCommands,
  ...linuxPermCommands,
  ...linuxUserCommands,
  ...linuxPackageCommands,
  ...linuxArchiveCommands,
  ...linuxPerfCommands,
  ...gitCommands,
  ...dockerCommands,
  ...k8sCommands,
  ...vimCommands,
  ...terminalCommands,
  ...curlCommands,
  ...systemdCommands,
  ...sshCommands,
  ...awkSedCommands,
  ...elasticsearchCommands,
  ...mongodbCommands,
  ...postgresqlCommands,
  ...npmCommands,
  ...nginxCommands,
  ...gradleCommands,
  ...mavenCommands,
  ...redisCommands,
  ...mysqlCommands,
  ...pythonCommands,
  ...goCommands,
  ...javaCommands,
  ...kafkaCommands
]

// 统计信息
const stats = {
  total: allCommands.length,
  categories: [...new Set(allCommands.map(cmd => cmd.category))]
}

console.log(`命令参考工具已加载 ${stats.total} 个命令，涵盖 ${stats.categories.length} 个类别`)

export default allCommands
