<template>
  <div class="data-visualization-tool">
    <el-card>
      <div slot="header">
        <span>数据可视化</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearAll">清空</el-button>
          <el-button size="small" @click="importData" type="primary">导入</el-button>
        </el-button-group>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <el-card shadow="hover">
            <div slot="header">
              <span>数据输入</span>
            </div>
            
            <el-tabs v-model="activeTab">
              <el-tab-pane label="JSON 数据">
                <el-input
                  type="textarea"
                  :rows="15"
                  v-model="jsonData"
                  placeholder="输入 JSON 格式的数据..."
                  @change="parseData"
                />
              </el-tab-pane>
              <el-tab-pane label="CSV 数据">
                <el-input
                  type="textarea"
                  :rows="15"
                  v-model="csvData"
                  placeholder="输入 CSV 格式的数据..."
                  @change="parseData"
                />
              </el-tab-pane>
              <el-tab-pane label="示例数据">
                <el-button @click="loadExample('bar')" type="primary" size="small" style="margin: 5px">柱状图示例</el-button>
                <el-button @click="loadExample('line')" type="primary" size="small" style="margin: 5px">折线图示例</el-button>
                <el-button @click="loadExample('pie')" type="primary" size="small" style="margin: 5px">饼图示例</el-button>
                <el-button @click="loadExample('scatter')" type="primary" size="small" style="margin: 5px">散点图示例</el-button>
              </el-tab-pane>
            </el-tabs>
          </el-card>

          <el-card shadow="hover" style="margin-top: 20px">
            <div slot="header">
              <span>图表配置</span>
            </div>
            
            <el-form :model="chartConfig" label-width="100px">
              <el-form-item label="图表类型">
                <el-select v-model="chartConfig.type" @change="updateChart" style="width: 100%">
                  <el-option label="柱状图" value="bar" />
                  <el-option label="折线图" value="line" />
                  <el-option label="饼图" value="pie" />
                  <el-option label="散点图" value="scatter" />
                  <el-option label="雷达图" value="radar" />
                  <el-option label="热力图" value="heatmap" />
                </el-select>
              </el-form-item>
              
              <el-form-item label="X 轴字段">
                <el-select v-model="chartConfig.xField" @change="updateChart" style="width: 100%">
                  <el-option
                    v-for="field in fields"
                    :key="field"
                    :label="field"
                    :value="field"
                  />
                </el-select>
              </el-form-item>
              
              <el-form-item label="Y 轴字段">
                <el-select v-model="chartConfig.yField" @change="updateChart" style="width: 100%">
                  <el-option
                    v-for="field in fields"
                    :key="field"
                    :label="field"
                    :value="field"
                  />
                </el-select>
              </el-form-item>
              
              <el-form-item label="图表标题">
                <el-input v-model="chartConfig.title" @change="updateChart" />
              </el-form-item>
              
              <el-form-item label="显示图例">
                <el-switch v-model="chartConfig.showLegend" @change="updateChart" />
              </el-form-item>
            </el-form>
          </el-card>
        </el-col>

        <el-col :span="12">
          <el-card shadow="hover">
            <div slot="header">
              <span>图表预览</span>
              <el-button size="small" @click="exportChart" type="success">导出图表</el-button>
            </div>
            
            <div id="chart-container" ref="chartContainer" style="width: 100%; height: 500px"></div>
          </el-card>

          <el-card shadow="hover" style="margin-top: 20px">
            <div slot="header">
              <span>数据预览</span>
            </div>
            
            <el-table
              :data="parsedData.slice(0, 10)"
              border
              style="width: 100%"
              size="small"
            >
              <el-table-column
                v-for="field in fields"
                :key="field"
                :prop="field"
                :label="field"
                min-width="100"
              />
            </el-table>
            <div v-if="parsedData.length > 10" style="text-align: center; margin-top: 10px; color: #909399">
              仅显示前 10 条数据
            </div>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'DataVisualizationTool',
  data() {
    return {
      activeTab: 'JSON 数据',
      jsonData: '',
      csvData: '',
      parsedData: [],
      fields: [],
      chartConfig: {
        type: 'bar',
        xField: '',
        yField: '',
        title: '数据可视化',
        showLegend: true
      },
      chart: null
    }
  },
  mounted() {
    this.loadExample('bar')
  },
  beforeDestroy() {
    if (this.chart) {
      this.chart.dispose()
    }
  },
  methods: {
    clearAll() {
      this.jsonData = ''
      this.csvData = ''
      this.parsedData = []
      this.fields = []
      this.chartConfig = {
        type: 'bar',
        xField: '',
        yField: '',
        title: '数据可视化',
        showLegend: true
      }
      this.updateChart()
    },
    parseData() {
      if (this.activeTab === 'JSON 数据') {
        this.parseJsonData()
      } else if (this.activeTab === 'CSV 数据') {
        this.parseCsvData()
      }
      this.updateChart()
    },
    parseJsonData() {
      try {
        const data = JSON.parse(this.jsonData)
        if (Array.isArray(data)) {
          this.parsedData = data
          if (data.length > 0) {
            this.fields = Object.keys(data[0])
            if (this.fields.length > 0) {
              this.chartConfig.xField = this.fields[0]
              this.chartConfig.yField = this.fields[1] || this.fields[0]
            }
          }
        } else {
          this.$message.error('JSON 数据必须是数组格式')
        }
      } catch (error) {
        this.$message.error('JSON 格式错误')
      }
    },
    parseCsvData() {
      try {
        const lines = this.csvData.split(/\r?\n/).filter(line => line.trim())
        if (lines.length < 2) {
          this.$message.error('CSV 数据至少需要包含表头和一行数据')
          return
        }
        
        const headers = this.parseCsvLine(lines[0])
        this.fields = headers
        
        const data = []
        for (let i = 1; i < lines.length; i++) {
          const values = this.parseCsvLine(lines[i])
          const row = {}
          headers.forEach((header, index) => {
            row[header] = values[index] || ''
          })
          data.push(row)
        }
        
        this.parsedData = data
        if (headers.length > 0) {
          this.chartConfig.xField = headers[0]
          this.chartConfig.yField = headers[1] || headers[0]
        }
      } catch (error) {
        this.$message.error('CSV 格式错误')
      }
    },
    parseCsvLine(line) {
      const result = []
      let current = ''
      let inQuotes = false
      
      for (let i = 0; i < line.length; i++) {
        const char = line[i]
        if (char === '"') {
          inQuotes = !inQuotes
        } else if (char === ',' && !inQuotes) {
          result.push(current)
          current = ''
        } else {
          current += char
        }
      }
      result.push(current)
      return result
    },
    loadExample(type) {
      if (type === 'bar') {
        this.jsonData = JSON.stringify([
          { name: '周一', value: 120 },
          { name: '周二', value: 200 },
          { name: '周三', value: 150 },
          { name: '周四', value: 80 },
          { name: '周五', value: 70 },
          { name: '周六', value: 110 },
          { name: '周日', value: 130 }
        ], null, 2)
      } else if (type === 'line') {
        this.jsonData = JSON.stringify([
          { month: '1月', sales: 120 },
          { month: '2月', sales: 190 },
          { month: '3月', sales: 300 },
          { month: '4月', sales: 250 },
          { month: '5月', sales: 270 },
          { month: '6月', sales: 350 }
        ], null, 2)
      } else if (type === 'pie') {
        this.jsonData = JSON.stringify([
          { name: '直接访问', value: 335 },
          { name: '邮件营销', value: 310 },
          { name: '联盟广告', value: 234 },
          { name: '视频广告', value: 135 },
          { name: '搜索引擎', value: 1548 }
        ], null, 2)
      } else if (type === 'scatter') {
        this.jsonData = JSON.stringify([
          { x: 10.0, y: 8.04 },
          { x: 8.0, y: 6.95 },
          { x: 13.0, y: 7.58 },
          { x: 9.0, y: 8.81 },
          { x: 11.0, y: 8.33 },
          { x: 14.0, y: 9.96 },
          { x: 6.0, y: 7.24 },
          { x: 4.0, y: 4.26 },
          { x: 12.0, y: 10.84 },
          { x: 7.0, y: 4.82 },
          { x: 5.0, y: 5.68 }
        ], null, 2)
      }
      this.activeTab = 'JSON 数据'
      this.parseData()
    },
    updateChart() {
      if (!this.chart) {
        this.initChart()
      }
      
      const option = this.getChartOption()
      this.chart.setOption(option)
    },
    initChart() {
      if (window.echarts) {
        this.chart = window.echarts.init(this.$refs.chartContainer)
        window.addEventListener('resize', () => {
          this.chart.resize()
        })
      } else {
        // 动态加载 ECharts
        const script = document.createElement('script')
        script.src = 'https://cdn.jsdelivr.net/npm/echarts@5.4.3/dist/echarts.min.js'
        script.onload = () => {
          this.chart = window.echarts.init(this.$refs.chartContainer)
          this.updateChart()
        }
        document.head.appendChild(script)
      }
    },
    getChartOption() {
      const option = {
        title: {
          text: this.chartConfig.title
        },
        tooltip: {
          trigger: 'axis'
        },
        legend: {
          show: this.chartConfig.showLegend
        },
        xAxis: {
          type: 'category',
          data: []
        },
        yAxis: {
          type: 'value'
        },
        series: []
      }
      
      if (this.parsedData.length === 0) {
        return option
      }
      
      if (this.chartConfig.type === 'pie') {
        delete option.xAxis
        delete option.yAxis
        option.series = [{
          name: this.chartConfig.yField || 'value',
          type: 'pie',
          radius: '50%',
          data: this.parsedData.map(item => ({
            name: item[this.chartConfig.xField || 'name'],
            value: parseFloat(item[this.chartConfig.yField || 'value']) || 0
          })),
          emphasis: {
            itemStyle: {
              shadowBlur: 10,
              shadowOffsetX: 0,
              shadowColor: 'rgba(0, 0, 0, 0.5)'
            }
          }
        }]
      } else if (this.chartConfig.type === 'scatter') {
        option.xAxis.type = 'value'
        option.series = [{
          name: '数据',
          type: 'scatter',
          data: this.parsedData.map(item => [
            parseFloat(item[this.chartConfig.xField || 'x']) || 0,
            parseFloat(item[this.chartConfig.yField || 'y']) || 0
          ])
        }]
      } else {
        option.xAxis.data = this.parsedData.map(item => item[this.chartConfig.xField])
        option.series = [{
          name: this.chartConfig.yField,
          type: this.chartConfig.type,
          data: this.parsedData.map(item => parseFloat(item[this.chartConfig.yField]) || 0)
        }]
      }
      
      return option
    },
    exportChart() {
      if (this.chart) {
        const url = this.chart.getDataURL({ pixelRatio: 2 })
        const link = document.createElement('a')
        link.href = url
        link.download = `chart_${new Date().toISOString().slice(0, 10)}.png`
        document.body.appendChild(link)
        link.click()
        document.body.removeChild(link)
      }
    },
    importData() {
      const input = document.createElement('input')
      input.type = 'file'
      input.accept = '.json,.csv'
      input.onchange = (e) => {
        const file = e.target.files[0]
        if (file) {
          const reader = new FileReader()
          reader.onload = (e) => {
            if (file.name.endsWith('.json')) {
              this.jsonData = e.target.result
              this.activeTab = 'JSON 数据'
            } else if (file.name.endsWith('.csv')) {
              this.csvData = e.target.result
              this.activeTab = 'CSV 数据'
            }
            this.parseData()
          }
          reader.readAsText(file)
        }
      }
      input.click()
    }
  }
}
</script>

<style lang="scss" scoped>
.data-visualization-tool {
  .header-actions {
    float: right;
  }
}
</style>