<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>Hex 编解码</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearAll">清空</el-button>
        </el-button-group>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="12">
          <div class="input-section">
            <div class="section-header">
              <span>文本</span>
              <el-button type="text" size="mini" @click="loadExample">加载示例</el-button>
            </div>
            <el-input
              v-model="text"
              type="textarea"
              :rows="10"
              placeholder="输入文本..."
            />
            <el-button type="primary" style="margin-top: 10px" @click="encode">
              编码为 Hex
            </el-button>
          </div>
        </el-col>
        
        <el-col :span="12">
          <div class="input-section">
            <div class="section-header">
              <span>Hex</span>
              <div>
                <el-button type="text" size="mini" @click="copyHex">复制</el-button>
                <el-button type="text" size="mini" @click="downloadHex">下载</el-button>
              </div>
            </div>
            <el-input
              v-model="hex"
              type="textarea"
              :rows="10"
              placeholder="输入十六进制..."
            />
            <el-button type="primary" style="margin-top: 10px" @click="decode">
              解码为文本
            </el-button>
          </div>
        </el-col>
      </el-row>
      
      <el-row style="margin-top: 20px">
        <el-col :span="24">
          <el-card shadow="never">
            <div slot="header">
              <span>信息</span>
            </div>
            <el-descriptions :column="4" border size="small">
              <el-descriptions-item label="文本长度">{{ text.length }}</el-descriptions-item>
              <el-descriptions-item label="Hex 长度">{{ hex.length }}</el-descriptions-item>
              <el-descriptions-item label="字节数">{{ byteCount }}</el-descriptions-item>
              <el-descriptions-item label="编码">{{ encoding }}</el-descriptions-item>
            </el-descriptions>
          </el-card>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'HexTool',
  data() {
    return {
      text: '',
      hex: '',
      encoding: 'UTF-8'
    }
  },
  computed: {
    byteCount() {
      return new Blob([this.text]).size
    }
  },
  methods: {
    encode() {
      if (!this.text) {
        this.$message.warning('请输入文本')
        return
      }
      
      try {
        const encoder = new TextEncoder()
        const bytes = encoder.encode(this.text)
        this.hex = Array.from(bytes)
          .map(b => b.toString(16).padStart(2, '0'))
          .join(' ')
        this.$message.success('编码成功')
      } catch (error) {
        this.$message.error('编码失败: ' + error.message)
      }
    },
    decode() {
      if (!this.hex) {
        this.$message.warning('请输入十六进制')
        return
      }
      
      try {
        const hexString = this.hex.replace(/\s/g, '')
        const bytes = new Uint8Array(hexString.match(/.{1,2}/g).map(byte => parseInt(byte, 16)))
        const decoder = new TextDecoder()
        this.text = decoder.decode(bytes)
        this.$message.success('解码成功')
      } catch (error) {
        this.$message.error('解码失败: ' + error.message)
      }
    },
    copyHex() {
      navigator.clipboard.writeText(this.hex).then(() => {
        this.$message.success('复制成功')
      }).catch(() => {
        this.$message.error('复制失败')
      })
    },
    downloadHex() {
      const blob = new Blob([this.hex], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = 'hex.txt'
      a.click()
      URL.revokeObjectURL(url)
      this.$message.success('下载成功')
    },
    loadExample() {
      this.text = 'Hello, World!'
      this.encode()
    },
    clearAll() {
      this.text = ''
      this.hex = ''
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .tool-card {
    .header-actions {
      float: right;
    }
  }

  .input-section {
    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
    }
  }
}
</style>
