<template>
  <div class="countdown-tool">
    <el-card>
      <div slot="header">
        <span>倒计时工具</span>
      </div>

      <el-tabs v-model="activeTab">
        <el-tab-pane label="目标倒计时" name="target">
          <el-form :model="targetForm" label-width="100px">
            <el-form-item label="目标时间">
              <el-date-picker
                v-model="targetForm.targetDate"
                type="datetime"
                placeholder="选择目标时间"
                style="width: 100%"
              />
            </el-form-item>
            <el-form-item label="标题">
              <el-input v-model="targetForm.title" placeholder="输入倒计时标题" />
            </el-form-item>
            <el-form-item>
              <el-button type="primary" @click="startTargetCountdown">开始倒计时</el-button>
              <el-button @click="clearTarget">清空</el-button>
            </el-form-item>
          </el-form>

          <div v-if="targetCountdown.active" class="countdown-display">
            <div class="countdown-title">{{ targetForm.title || '倒计时' }}</div>
            <div class="countdown-timer">
              <div class="time-block">
                <div class="time-value">{{ targetCountdown.days }}</div>
                <div class="time-label">天</div>
              </div>
              <div class="time-separator">:</div>
              <div class="time-block">
                <div class="time-value">{{ targetCountdown.hours }}</div>
                <div class="time-label">时</div>
              </div>
              <div class="time-separator">:</div>
              <div class="time-block">
                <div class="time-value">{{ targetCountdown.minutes }}</div>
                <div class="time-label">分</div>
              </div>
              <div class="time-separator">:</div>
              <div class="time-block">
                <div class="time-value">{{ targetCountdown.seconds }}</div>
                <div class="time-label">秒</div>
              </div>
            </div>
            <div class="countdown-message" v-if="targetCountdown.expired">
              <el-alert title="时间到！" type="success" :closable="false" center />
            </div>
          </div>
        </el-tab-pane>

        <el-tab-pane label="番茄钟" name="pomodoro">
          <div class="pomodoro-section">
            <div class="pomodoro-modes">
              <el-radio-group v-model="pomodoro.mode" @change="resetPomodoro">
                <el-radio-button label="work">专注 (25分钟)</el-radio-button>
                <el-radio-button label="shortBreak">短休息 (5分钟)</el-radio-button>
                <el-radio-button label="longBreak">长休息 (15分钟)</el-radio-button>
              </el-radio-group>
            </div>

            <div class="pomodoro-timer">
              <div class="timer-circle">
                <svg viewBox="0 0 100 100">
                  <circle class="timer-bg" cx="50" cy="50" r="45" />
                  <circle 
                    class="timer-progress" 
                    cx="50" 
                    cy="50" 
                    r="45"
                    :style="pomodoroCircleStyle"
                  />
                </svg>
                <div class="timer-text">{{ pomodoroDisplay }}</div>
              </div>
            </div>

            <div class="pomodoro-controls">
              <el-button 
                :type="pomodoro.running ? 'danger' : 'primary'" 
                size="large"
                @click="togglePomodoro"
              >
                {{ pomodoro.running ? '暂停' : '开始' }}
              </el-button>
              <el-button size="large" @click="resetPomodoro">重置</el-button>
            </div>

            <div class="pomodoro-stats">
              <div class="stat-item">
                <div class="stat-value">{{ pomodoro.completedSessions }}</div>
                <div class="stat-label">完成专注</div>
              </div>
              <div class="stat-item">
                <div class="stat-value">{{ formatDuration(pomodoro.totalFocusTime) }}</div>
                <div class="stat-label">总专注时间</div>
              </div>
            </div>
          </div>
        </el-tab-pane>

        <el-tab-pane label="快速计时器" name="quick">
          <el-row :gutter="20">
            <el-col :span="8">
              <el-form-item label="小时">
                <el-input-number v-model="quickTimer.hours" :min="0" :max="99" style="width: 100%" />
              </el-form-item>
            </el-col>
            <el-col :span="8">
              <el-form-item label="分钟">
                <el-input-number v-model="quickTimer.minutes" :min="0" :max="59" style="width: 100%" />
              </el-form-item>
            </el-col>
            <el-col :span="8">
              <el-form-item label="秒">
                <el-input-number v-model="quickTimer.seconds" :min="0" :max="59" style="width: 100%" />
              </el-form-item>
            </el-col>
          </el-row>

          <div class="quick-timer-display" v-if="quickTimer.running || quickTimer.remaining > 0">
            <div class="quick-time">{{ formatQuickTime(quickTimer.remaining) }}</div>
            <el-progress 
              :percentage="quickTimerPercentage" 
              :status="quickTimer.remaining === 0 ? 'success' : ''"
            />
          </div>

          <div class="action-buttons">
            <el-button type="primary" @click="startQuickTimer" v-if="!quickTimer.running">开始</el-button>
            <el-button type="danger" @click="pauseQuickTimer" v-else>暂停</el-button>
            <el-button @click="resetQuickTimer">重置</el-button>
          </div>

          <el-divider>预设时间</el-divider>

          <div class="preset-buttons">
            <el-button @click="setQuickTimer(0, 1, 0)">1分钟</el-button>
            <el-button @click="setQuickTimer(0, 5, 0)">5分钟</el-button>
            <el-button @click="setQuickTimer(0, 10, 0)">10分钟</el-button>
            <el-button @click="setQuickTimer(0, 15, 0)">15分钟</el-button>
            <el-button @click="setQuickTimer(0, 25, 0)">25分钟</el-button>
            <el-button @click="setQuickTimer(0, 30, 0)">30分钟</el-button>
          </div>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'CountdownTool',
  data() {
    return {
      activeTab: 'target',
      targetForm: {
        targetDate: null,
        title: ''
      },
      targetCountdown: {
        active: false,
        expired: false,
        days: 0,
        hours: 0,
        minutes: 0,
        seconds: 0
      },
      pomodoro: {
        mode: 'work',
        running: false,
        remaining: 25 * 60,
        totalTime: 25 * 60,
        completedSessions: 0,
        totalFocusTime: 0
      },
      quickTimer: {
        hours: 0,
        minutes: 5,
        seconds: 0,
        running: false,
        remaining: 0,
        total: 0
      },
      timers: []
    }
  },
  computed: {
    pomodoroDisplay() {
      const minutes = Math.floor(this.pomodoro.remaining / 60)
      const seconds = this.pomodoro.remaining % 60
      return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`
    },
    pomodoroCircleStyle() {
      const circumference = 2 * Math.PI * 45
      const progress = (this.pomodoro.totalTime - this.pomodoro.remaining) / this.pomodoro.totalTime
      const offset = circumference - progress * circumference
      return {
        strokeDasharray: circumference,
        strokeDashoffset: offset
      }
    },
    quickTimerPercentage() {
      if (this.quickTimer.total === 0) return 0
      return Math.round((this.quickTimer.total - this.quickTimer.remaining) / this.quickTimer.total * 100)
    }
  },
  beforeDestroy() {
    this.timers.forEach(timer => clearInterval(timer))
  },
  methods: {
    startTargetCountdown() {
      if (!this.targetForm.targetDate) {
        this.$message.warning('请选择目标时间')
        return
      }
      
      this.targetCountdown.active = true
      this.targetCountdown.expired = false
      
      const timer = setInterval(() => {
        const now = new Date().getTime()
        const target = new Date(this.targetForm.targetDate).getTime()
        const diff = target - now
        
        if (diff <= 0) {
          this.targetCountdown.expired = true
          this.targetCountdown.days = 0
          this.targetCountdown.hours = 0
          this.targetCountdown.minutes = 0
          this.targetCountdown.seconds = 0
          clearInterval(timer)
          this.$notify({
            title: '倒计时结束',
            message: this.targetForm.title || '时间到了！',
            type: 'success'
          })
        } else {
          this.targetCountdown.days = Math.floor(diff / (1000 * 60 * 60 * 24))
          this.targetCountdown.hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60))
          this.targetCountdown.minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60))
          this.targetCountdown.seconds = Math.floor((diff % (1000 * 60)) / 1000)
        }
      }, 1000)
      
      this.timers.push(timer)
    },
    clearTarget() {
      this.targetForm.targetDate = null
      this.targetForm.title = ''
      this.targetCountdown.active = false
      this.targetCountdown.expired = false
    },
    togglePomodoro() {
      if (this.pomodoro.running) {
        this.pomodoro.running = false
      } else {
        this.pomodoro.running = true
        const timer = setInterval(() => {
          if (!this.pomodoro.running) {
            clearInterval(timer)
            return
          }
          
          if (this.pomodoro.remaining > 0) {
            this.pomodoro.remaining--
            if (this.pomodoro.mode === 'work') {
              this.pomodoro.totalFocusTime++
            }
          } else {
            this.pomodoro.running = false
            if (this.pomodoro.mode === 'work') {
              this.pomodoro.completedSessions++
            }
            this.$notify({
              title: '番茄钟结束',
              message: this.pomodoro.mode === 'work' ? '专注时间结束，休息一下吧！' : '休息结束，继续专注！',
              type: 'success'
            })
          }
        }, 1000)
        this.timers.push(timer)
      }
    },
    resetPomodoro() {
      this.pomodoro.running = false
      const times = {
        work: 25 * 60,
        shortBreak: 5 * 60,
        longBreak: 15 * 60
      }
      this.pomodoro.totalTime = times[this.pomodoro.mode]
      this.pomodoro.remaining = times[this.pomodoro.mode]
    },
    startQuickTimer() {
      const totalSeconds = this.quickTimer.hours * 3600 + this.quickTimer.minutes * 60 + this.quickTimer.seconds
      if (totalSeconds === 0) {
        this.$message.warning('请设置时间')
        return
      }
      
      this.quickTimer.total = totalSeconds
      this.quickTimer.remaining = totalSeconds
      this.quickTimer.running = true
      
      const timer = setInterval(() => {
        if (!this.quickTimer.running) {
          clearInterval(timer)
          return
        }
        
        if (this.quickTimer.remaining > 0) {
          this.quickTimer.remaining--
        } else {
          this.quickTimer.running = false
          this.$notify({
            title: '计时器结束',
            message: '时间到了！',
            type: 'success'
          })
        }
      }, 1000)
      
      this.timers.push(timer)
    },
    pauseQuickTimer() {
      this.quickTimer.running = false
    },
    resetQuickTimer() {
      this.quickTimer.running = false
      this.quickTimer.remaining = 0
      this.quickTimer.total = 0
    },
    setQuickTimer(hours, minutes, seconds) {
      this.quickTimer.hours = hours
      this.quickTimer.minutes = minutes
      this.quickTimer.seconds = seconds
      this.resetQuickTimer()
    },
    formatQuickTime(seconds) {
      const hours = Math.floor(seconds / 3600)
      const minutes = Math.floor((seconds % 3600) / 60)
      const secs = seconds % 60
      return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(secs).padStart(2, '0')}`
    },
    formatDuration(seconds) {
      const hours = Math.floor(seconds / 3600)
      const minutes = Math.floor((seconds % 3600) / 60)
      if (hours > 0) {
        return `${hours}小时${minutes}分钟`
      }
      return `${minutes}分钟`
    }
  }
}
</script>

<style scoped>
.countdown-tool {
  padding: 20px;
}

.countdown-display {
  text-align: center;
  padding: 40px;
  background: #f5f7fa;
  border-radius: 8px;
  margin-top: 20px;
}

.countdown-title {
  font-size: 24px;
  color: #606266;
  margin-bottom: 30px;
}

.countdown-timer {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
}

.time-block {
  text-align: center;
}

.time-value {
  font-size: 48px;
  font-weight: bold;
  color: #409eff;
  min-width: 80px;
}

.time-label {
  font-size: 14px;
  color: #909399;
  margin-top: 5px;
}

.time-separator {
  font-size: 48px;
  font-weight: bold;
  color: #409eff;
  padding-bottom: 20px;
}

.countdown-message {
  margin-top: 30px;
}

.pomodoro-section {
  text-align: center;
  padding: 20px;
}

.pomodoro-modes {
  margin-bottom: 30px;
}

.pomodoro-timer {
  margin: 30px 0;
}

.timer-circle {
  position: relative;
  width: 250px;
  height: 250px;
  margin: 0 auto;
}

.timer-circle svg {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.timer-bg {
  fill: none;
  stroke: #e4e7ed;
  stroke-width: 5;
}

.timer-progress {
  fill: none;
  stroke: #409eff;
  stroke-width: 5;
  stroke-linecap: round;
  transition: stroke-dashoffset 1s linear;
}

.timer-text {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 48px;
  font-weight: bold;
  color: #303133;
}

.pomodoro-controls {
  margin: 30px 0;
}

.pomodoro-stats {
  display: flex;
  justify-content: center;
  gap: 40px;
  margin-top: 30px;
}

.stat-item {
  text-align: center;
}

.stat-value {
  font-size: 24px;
  font-weight: bold;
  color: #409eff;
}

.stat-label {
  font-size: 14px;
  color: #909399;
  margin-top: 5px;
}

.quick-timer-display {
  text-align: center;
  padding: 30px;
  background: #f5f7fa;
  border-radius: 8px;
  margin: 20px 0;
}

.quick-time {
  font-size: 48px;
  font-weight: bold;
  color: #409eff;
  margin-bottom: 20px;
}

.action-buttons {
  text-align: center;
  margin: 20px 0;
}

.preset-buttons {
  text-align: center;
  margin-top: 20px;
}

.preset-buttons .el-button {
  margin: 5px;
}
</style>
