<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>JSON / XML 互转</span>
        <el-button size="small" @click="clearAll">清空</el-button>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="11">
          <div class="input-section">
            <div class="section-header">
              <span>JSON</span>
              <el-tag size="mini" type="primary">输入或输出</el-tag>
            </div>
            <el-input
              v-model="jsonText"
              type="textarea"
              :rows="15"
              placeholder='输入 JSON，如: {"name": "张三", "age": 25}'
              @input="onJsonChange"
            />
          </div>
        </el-col>
        
        <el-col :span="2" class="actions-col">
          <div class="action-buttons">
            <el-button type="primary" circle @click="jsonToXml" title="JSON → XML">
              <i class="el-icon-right"></i>
            </el-button>
            <span class="action-label">JSON转XML</span>
            <el-button type="success" circle @click="xmlToJson" title="XML → JSON">
              <i class="el-icon-back"></i>
            </el-button>
            <span class="action-label">XML转JSON</span>
          </div>
        </el-col>
        
        <el-col :span="11">
          <div class="output-section">
            <div class="section-header">
              <span>XML</span>
              <el-tag size="mini" type="success">输入或输出</el-tag>
              <el-button type="text" size="mini" @click="copyXml">复制</el-button>
            </div>
            <el-input
              v-model="xmlText"
              type="textarea"
              :rows="15"
              placeholder="输入 XML，如: <root><name>张三</name><age>25</age></root>"
              @input="onXmlChange"
            />
          </div>
        </el-col>
      </el-row>

      <el-row style="margin-top: 20px">
        <el-col :span="24">
          <el-alert type="info" :closable="false" show-icon>
            <template slot="title">
              使用提示：在任意一侧输入内容，点击中间按钮即可转换到另一侧
            </template>
          </el-alert>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'JsonXmlTool',
  data() {
    return {
      jsonText: '',
      xmlText: '',
      isConverting: false
    }
  },
  methods: {
    onJsonChange() {
      if (this.isConverting) return
    },
    onXmlChange() {
      if (this.isConverting) return
    },
    jsonToXml() {
      if (!this.jsonText.trim()) {
        this.$message.warning('请输入 JSON 内容')
        return
      }
      
      try {
        const obj = JSON.parse(this.jsonText)
        this.isConverting = true
        this.xmlText = this.convertJsonToXml(obj, 'root')
        this.isConverting = false
        this.$message.success('转换成功')
      } catch (e) {
        this.$message.error('JSON 格式错误: ' + e.message)
      }
    },
    convertJsonToXml(obj, rootName) {
      let xml = '<?xml version="1.0" encoding="UTF-8"?>\n'
      xml += this.objectToXml(obj, rootName, 0)
      return xml
    },
    objectToXml(obj, tagName, indent) {
      const spaces = '  '.repeat(indent)
      let result = ''
      
      if (typeof obj !== 'object' || obj === null) {
        result += `${spaces}<${tagName}>${this.escapeXml(obj)}</${tagName}>\n`
        return result
      }
      
      if (Array.isArray(obj)) {
        obj.forEach((item, index) => {
          result += this.objectToXml(item, 'item', indent)
        })
        return result
      }
      
      result += `${spaces}<${tagName}>\n`
      
      for (const key in obj) {
        if (obj.hasOwnProperty(key)) {
          const value = obj[key]
          const safeKey = this.safeTagName(key)
          
          if (Array.isArray(value)) {
            value.forEach(item => {
              result += this.objectToXml(item, safeKey, indent + 1)
            })
          } else if (typeof value === 'object' && value !== null) {
            result += this.objectToXml(value, safeKey, indent + 1)
          } else {
            result += `${spaces}  <${safeKey}>${this.escapeXml(value)}</${safeKey}>\n`
          }
        }
      }
      
      result += `${spaces}</${tagName}>\n`
      return result
    },
    xmlToJson() {
      if (!this.xmlText.trim()) {
        this.$message.warning('请输入 XML 内容')
        return
      }
      
      try {
        const parser = new DOMParser()
        const doc = parser.parseFromString(this.xmlText, 'text/xml')
        
        const errorNode = doc.querySelector('parsererror')
        if (errorNode) {
          throw new Error('XML 格式错误')
        }
        
        this.isConverting = true
        const result = this.xmlNodeToJson(doc.documentElement)
        this.jsonText = JSON.stringify(result, null, 2)
        this.isConverting = false
        this.$message.success('转换成功')
      } catch (e) {
        this.$message.error('XML 解析错误: ' + e.message)
      }
    },
    xmlNodeToJson(node) {
      const result = {}
      
      if (node.attributes && node.attributes.length > 0) {
        result['@attributes'] = {}
        for (let i = 0; i < node.attributes.length; i++) {
          const attr = node.attributes[i]
          result['@attributes'][attr.name] = attr.value
        }
      }
      
      if (node.childNodes && node.childNodes.length > 0) {
        let hasElementChild = false
        const childResults = {}
        
        for (let i = 0; i < node.childNodes.length; i++) {
          const child = node.childNodes[i]
          
          if (child.nodeType === 1) {
            hasElementChild = true
            const childName = child.nodeName
            const childJson = this.xmlNodeToJson(child)
            
            if (childResults[childName]) {
              if (!Array.isArray(childResults[childName])) {
                childResults[childName] = [childResults[childName]]
              }
              childResults[childName].push(childJson)
            } else {
              childResults[childName] = childJson
            }
          }
        }
        
        if (hasElementChild) {
          Object.assign(result, childResults)
        } else {
          const text = node.textContent.trim()
          if (text) {
            return this.parseValue(text)
          }
        }
      }
      
      return Object.keys(result).length > 0 ? result : ''
    },
    parseValue(value) {
      if (value === 'true') return true
      if (value === 'false') return false
      if (value === 'null') return null
      if (!isNaN(value) && value.trim() !== '') {
        return Number(value)
      }
      return value
    },
    escapeXml(value) {
      if (value === null || value === undefined) return ''
      return String(value)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&apos;')
    },
    safeTagName(name) {
      return name.replace(/[^a-zA-Z0-9_-]/g, '_')
    },
    clearAll() {
      this.jsonText = ''
      this.xmlText = ''
    },
    copyXml() {
      if (!this.xmlText) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.xmlText).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .input-section, .output-section {
    .section-header {
      display: flex;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
      gap: 10px;

      .el-button {
        margin-left: auto;
      }
    }
  }

  .actions-col {
    display: flex;
    align-items: center;
    justify-content: center;

    .action-buttons {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 10px;

      .action-label {
        font-size: 12px;
        color: #606266;
        margin-bottom: 10px;
      }
    }
  }
}
</style>
