<template>
  <div class="percentage-tool">
    <el-card>
      <div slot="header">
        <span>百分比计算器</span>
      </div>

      <el-tabs v-model="activeTab">
        <el-tab-pane label="基础计算" name="basic">
          <el-row :gutter="20">
            <el-col :span="12">
              <el-form label-width="120px">
                <el-form-item label="数值">
                  <el-input-number v-model="basic.value" :min="0" :precision="2" style="width: 200px" />
                </el-form-item>
                <el-form-item label="百分比">
                  <el-input-number v-model="basic.percent" :min="0" :max="100" :precision="2" style="width: 200px" />
                  <span style="margin-left: 10px">%</span>
                </el-form-item>
              </el-form>
              <el-divider>计算结果</el-divider>
              <div class="result-box">
                <div class="result-item">
                  <span class="label">{{ basic.value }} 的 {{ basic.percent }}% =</span>
                  <span class="value">{{ basic.result1 }}</span>
                </div>
                <div class="result-item">
                  <span class="label">{{ basic.value }} 增加 {{ basic.percent }}% =</span>
                  <span class="value">{{ basic.result2 }}</span>
                </div>
                <div class="result-item">
                  <span class="label">{{ basic.value }} 减少 {{ basic.percent }}% =</span>
                  <span class="value">{{ basic.result3 }}</span>
                </div>
              </div>
            </el-col>
            <el-col :span="12">
              <el-divider>百分比可视化</el-divider>
              <div class="percent-visual">
                <el-progress type="circle" :percentage="basic.percent" :width="150" />
              </div>
            </el-col>
          </el-row>
        </el-tab-pane>

        <el-tab-pane label="百分比转换" name="convert">
          <el-row :gutter="20">
            <el-col :span="12">
              <el-form label-width="120px">
                <el-form-item label="部分值">
                  <el-input-number v-model="convert.part" :precision="2" style="width: 200px" />
                </el-form-item>
                <el-form-item label="整体值">
                  <el-input-number v-model="convert.total" :precision="2" style="width: 200px" />
                </el-form-item>
              </el-form>
              <el-divider>计算结果</el-divider>
              <div class="result-box">
                <div class="result-item">
                  <span class="label">{{ convert.part }} 占 {{ convert.total }} 的百分比：</span>
                  <span class="value">{{ convert.result }}%</span>
                </div>
              </div>
            </el-col>
            <el-col :span="12">
              <el-divider>比例可视化</el-divider>
              <div class="ratio-visual">
                <div class="ratio-bar">
                  <div class="ratio-fill" :style="{ width: convert.result + '%' }"></div>
                </div>
                <div class="ratio-text">{{ convert.result }}%</div>
              </div>
            </el-col>
          </el-row>
        </el-tab-pane>

        <el-tab-pane label="增减百分比" name="change">
          <el-row :gutter="20">
            <el-col :span="12">
              <el-form label-width="120px">
                <el-form-item label="原始值">
                  <el-input-number v-model="change.oldValue" :precision="2" style="width: 200px" />
                </el-form-item>
                <el-form-item label="新值">
                  <el-input-number v-model="change.newValue" :precision="2" style="width: 200px" />
                </el-form-item>
              </el-form>
              <el-divider>计算结果</el-divider>
              <div class="result-box">
                <div class="result-item">
                  <span class="label">变化量：</span>
                  <span class="value" :class="{ positive: change.diff > 0, negative: change.diff < 0 }">
                    {{ change.diff > 0 ? '+' : '' }}{{ change.diff }}
                  </span>
                </div>
                <div class="result-item">
                  <span class="label">变化百分比：</span>
                  <span class="value" :class="{ positive: change.percent > 0, negative: change.percent < 0 }">
                    {{ change.percent > 0 ? '+' : '' }}{{ change.percent }}%
                  </span>
                </div>
              </div>
            </el-col>
            <el-col :span="12">
              <el-divider>变化趋势</el-divider>
              <div class="trend-visual">
                <div class="trend-arrow" :class="{ up: change.percent > 0, down: change.percent < 0 }">
                  <i :class="change.percent >= 0 ? 'el-icon-top' : 'el-icon-bottom'"></i>
                  <span>{{ Math.abs(change.percent) }}%</span>
                </div>
              </div>
            </el-col>
          </el-row>
        </el-tab-pane>

        <el-tab-pane label="折扣计算" name="discount">
          <el-row :gutter="20">
            <el-col :span="12">
              <el-form label-width="120px">
                <el-form-item label="原价">
                  <el-input-number v-model="discount.originalPrice" :min="0" :precision="2" style="width: 200px" />
                </el-form-item>
                <el-form-item label="折扣">
                  <el-input-number v-model="discount.discountRate" :min="0" :max="100" :precision="0" style="width: 200px" />
                  <span style="margin-left: 10px">% (即 {{ discount.discountRate / 10 }}折)</span>
                </el-form-item>
              </el-form>
              <el-divider>计算结果</el-divider>
              <div class="result-box">
                <div class="result-item">
                  <span class="label">折扣金额：</span>
                  <span class="value discount">-¥{{ discount.discountAmount }}</span>
                </div>
                <div class="result-item">
                  <span class="label">折后价格：</span>
                  <span class="value price">¥{{ discount.finalPrice }}</span>
                </div>
                <div class="result-item">
                  <span class="label">节省：</span>
                  <span class="value save">¥{{ discount.discountAmount }}</span>
                </div>
              </div>
            </el-col>
            <el-col :span="12">
              <el-divider>价格对比</el-divider>
              <div class="price-compare">
                <div class="price-item original">
                  <span class="label">原价</span>
                  <span class="price">¥{{ discount.originalPrice }}</span>
                </div>
                <div class="price-arrow">
                  <i class="el-icon-bottom"></i>
                </div>
                <div class="price-item final">
                  <span class="label">折后价</span>
                  <span class="price">¥{{ discount.finalPrice }}</span>
                </div>
              </div>
            </el-col>
          </el-row>
        </el-tab-pane>
      </el-tabs>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'PercentageTool',
  data() {
    return {
      activeTab: 'basic',
      basic: {
        value: 100,
        percent: 20
      },
      convert: {
        part: 25,
        total: 100
      },
      change: {
        oldValue: 100,
        newValue: 120
      },
      discount: {
        originalPrice: 100,
        discountRate: 80
      }
    }
  },
  computed: {
    basicResults() {
      const { value, percent } = this.basic
      return {
        result1: (value * percent / 100).toFixed(2),
        result2: (value * (1 + percent / 100)).toFixed(2),
        result3: (value * (1 - percent / 100)).toFixed(2)
      }
    },
    'basic.result1'() {
      return (this.basic.value * this.basic.percent / 100).toFixed(2)
    },
    'basic.result2'() {
      return (this.basic.value * (1 + this.basic.percent / 100)).toFixed(2)
    },
    'basic.result3'() {
      return (this.basic.value * (1 - this.basic.percent / 100)).toFixed(2)
    },
    'convert.result'() {
      if (this.convert.total === 0) return 0
      return ((this.convert.part / this.convert.total) * 100).toFixed(2)
    },
    'change.diff'() {
      return (this.change.newValue - this.change.oldValue).toFixed(2)
    },
    'change.percent'() {
      if (this.change.oldValue === 0) return 0
      return ((this.change.newValue - this.change.oldValue) / this.change.oldValue * 100).toFixed(2)
    },
    'discount.discountAmount'() {
      return (this.discount.originalPrice * (1 - this.discount.discountRate / 100)).toFixed(2)
    },
    'discount.finalPrice'() {
      return (this.discount.originalPrice * this.discount.discountRate / 100).toFixed(2)
    }
  }
}
</script>

<style scoped>
.percentage-tool {
  padding: 20px;
}

.result-box {
  background: #f5f7fa;
  border-radius: 8px;
  padding: 20px;
}

.result-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 0;
  border-bottom: 1px solid #ebeef5;
}

.result-item:last-child {
  border-bottom: none;
}

.result-item .label {
  color: #606266;
}

.result-item .value {
  font-size: 20px;
  font-weight: bold;
  color: #409eff;
}

.result-item .value.positive {
  color: #67c23a;
}

.result-item .value.negative {
  color: #f56c6c;
}

.result-item .value.discount {
  color: #f56c6c;
}

.result-item .value.price {
  color: #e6a23c;
  font-size: 24px;
}

.result-item .value.save {
  color: #67c23a;
}

.percent-visual {
  display: flex;
  justify-content: center;
  padding: 30px;
}

.ratio-visual {
  padding: 30px;
}

.ratio-bar {
  height: 30px;
  background: #e4e7ed;
  border-radius: 15px;
  overflow: hidden;
}

.ratio-fill {
  height: 100%;
  background: linear-gradient(90deg, #409eff, #67c23a);
  border-radius: 15px;
  transition: width 0.3s;
}

.ratio-text {
  text-align: center;
  margin-top: 10px;
  font-size: 18px;
  font-weight: bold;
  color: #409eff;
}

.trend-visual {
  display: flex;
  justify-content: center;
  padding: 40px;
}

.trend-arrow {
  display: flex;
  flex-direction: column;
  align-items: center;
  font-size: 48px;
}

.trend-arrow.up {
  color: #67c23a;
}

.trend-arrow.down {
  color: #f56c6c;
}

.trend-arrow i {
  font-size: 64px;
}

.trend-arrow span {
  font-size: 24px;
  font-weight: bold;
}

.price-compare {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 20px;
}

.price-item {
  text-align: center;
  padding: 15px 30px;
  border-radius: 8px;
}

.price-item.original {
  background: #fef0f0;
}

.price-item.final {
  background: #f0f9eb;
}

.price-item .label {
  display: block;
  font-size: 12px;
  color: #909399;
  margin-bottom: 5px;
}

.price-item .price {
  font-size: 24px;
  font-weight: bold;
  color: #303133;
}

.price-arrow {
  padding: 10px;
  color: #67c23a;
  font-size: 24px;
}
</style>
