<template>
  <div class="markdown-to-ppt-tool">
    <el-card shadow="never" class="box-card">
      <template slot="header">
        <div class="card-header">
          <span>Markdown 转 PPT</span>
          <el-tooltip content="将 Markdown 文本转换为演示文稿" placement="top">
            <el-button type="info" size="small" icon="el-icon-question"></el-button>
          </el-tooltip>
        </div>
      </template>
      
      <el-row :gutter="20">
        <el-col :span="12">
          <el-form label-width="80px">
            <el-form-item label="Markdown 内容">
              <el-input
                type="textarea"
                v-model="markdownContent"
                :rows="15"
                placeholder="请输入 Markdown 内容，使用 # 表示标题层级"
              ></el-input>
            </el-form-item>
            
            <el-form-item label="PPT 标题">
              <el-input v-model="pptTitle" placeholder="请输入演示文稿标题"></el-input>
            </el-form-item>
            
            <el-form-item label="主题">
              <el-select v-model="theme" placeholder="选择主题">
                <el-option label="默认" value="default"></el-option>
                <el-option label="深色" value="dark"></el-option>
                <el-option label="蓝色" value="blue"></el-option>
                <el-option label="绿色" value="green"></el-option>
              </el-select>
            </el-form-item>
            
            <el-form-item>
              <el-button type="primary" @click="convertToPpt" :loading="loading">
                转换为 PPT
              </el-button>
              <el-button @click="reset">重置</el-button>
            </el-form-item>
          </el-form>
        </el-col>
        
        <el-col :span="12">
          <div class="preview-container">
            <h3>预览</h3>
            <div class="ppt-preview" v-if="slides.length > 0">
              <div 
                v-for="(slide, index) in slides" 
                :key="index"
                class="slide"
                :class="theme"
              >
                <div class="slide-header" v-if="index === 0">
                  <h1>{{ pptTitle || '演示文稿' }}</h1>
                </div>
                <div class="slide-content" v-else>
                  <h2 v-if="slide.level === 1">{{ slide.content }}</h2>
                  <h3 v-else-if="slide.level === 2">{{ slide.content }}</h3>
                  <div v-else class="slide-text">{{ slide.content }}</div>
                </div>
              </div>
            </div>
            <div v-else class="empty-preview">
              转换后将在此处显示预览
            </div>
            
            <div class="export-section" v-if="slides.length > 0">
              <el-button type="success" @click="exportPpt">
                导出 PPT
              </el-button>
            </div>
          </div>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'MarkdownToPptTool',
  data() {
    return {
      markdownContent: '# 演示文稿标题\n\n## 第一部分\n\n这是第一部分的内容\n\n- 要点 1\n- 要点 2\n- 要点 3\n\n## 第二部分\n\n这是第二部分的内容\n\n### 子标题\n\n更多内容...',
      pptTitle: '演示文稿',
      theme: 'default',
      slides: [],
      loading: false
    }
  },
  methods: {
    convertToPpt() {
      this.loading = true
      try {
        this.slides = []
        
        // 添加封面 slide
        this.slides.push({
          level: 0,
          content: this.pptTitle
        })
        
        // 解析 Markdown 内容
        const lines = this.markdownContent.split('\n')
        let currentSlide = null
        
        lines.forEach(line => {
          line = line.trim()
          if (line.startsWith('#')) {
            // 处理标题，创建新 slide
            const level = line.match(/^#+/) ? line.match(/^#+/) : [""]
            const levelNum = level[0].length || 1
            const content = line.replace(/^#+/, '').trim()
            
            if (levelNum <= 2) {
              // 一级和二级标题创建新 slide
              if (currentSlide) {
                this.slides.push(currentSlide)
              }
              currentSlide = {
                level: levelNum,
                content: content
              }
            } else {
              // 三级及以下标题作为内容
              if (currentSlide) {
                currentSlide.content += '\n### ' + content
              }
            }
          } else if (line) {
            // 处理内容
            if (currentSlide) {
              currentSlide.content += '\n' + line
            } else {
              // 如果没有标题，创建默认 slide
              currentSlide = {
                level: 1,
                content: line
              }
            }
          }
        })
        
        // 添加最后一个 slide
        if (currentSlide) {
          this.slides.push(currentSlide)
        }
      } catch (error) {
        this.$message.error('转换失败，请检查 Markdown 格式')
      } finally {
        this.loading = false
      }
    },
    reset() {
      this.markdownContent = '# 演示文稿标题\n\n## 第一部分\n\n这是第一部分的内容\n\n- 要点 1\n- 要点 2\n- 要点 3\n\n## 第二部分\n\n这是第二部分的内容\n\n### 子标题\n\n更多内容...'
      this.pptTitle = '演示文稿'
      this.theme = 'default'
      this.slides = []
    },
    exportPpt() {
      // 这里实现导出功能
      // 由于是纯前端实现，我们可以生成一个 HTML 文件作为 PPT
      let html = '<!DOCTYPE html>\n'
      html += '<html lang="zh-CN">\n'
      html += '<head>\n'
      html += '  <meta charset="UTF-8">\n'
      html += '  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n'
      html += '  <title>' + this.pptTitle + '</title>\n'
      html += '  <style>\n'
      html += '    * {\n'
      html += '      margin: 0;\n'
      html += '      padding: 0;\n'
      html += '      box-sizing: border-box;\n'
      html += '    }\n'
      html += '    body {\n'
      html += '      font-family: Arial, sans-serif;\n'
      html += '      line-height: 1.6;\n'
      html += '    }\n'
      html += '    .slide {\n'
      html += '      width: 100vw;\n'
      html += '      height: 100vh;\n'
      html += '      display: flex;\n'
      html += '      flex-direction: column;\n'
      html += '      justify-content: center;\n'
      html += '      align-items: center;\n'
      html += '      padding: 2rem;\n'
      html += '      page-break-after: always;\n'
      html += '    }\n'
      html += '    .slide-header {\n'
      html += '      text-align: center;\n'
      html += '    }\n'
      html += '    .slide-header h1 {\n'
      html += '      font-size: 2.5rem;\n'
      html += '      margin-bottom: 2rem;\n'
      html += '    }\n'
      html += '    .slide-content {\n'
      html += '      width: 100%;\n'
      html += '      max-width: 800px;\n'
      html += '    }\n'
      html += '    .slide-content h2 {\n'
      html += '      font-size: 2rem;\n'
      html += '      margin-bottom: 1.5rem;\n'
      html += '      text-align: center;\n'
      html += '    }\n'
      html += '    .slide-content h3 {\n'
      html += '      font-size: 1.5rem;\n'
      html += '      margin-bottom: 1rem;\n'
      html += '    }\n'
      html += '    .slide-text {\n'
      html += '      font-size: 1.1rem;\n'
      html += '      line-height: 1.8;\n'
      html += '    }\n'
      html += '    .slide-text ul {\n'
      html += '      margin-left: 2rem;\n'
      html += '      margin-top: 1rem;\n'
      html += '    }\n'
      html += '    .slide-text li {\n'
      html += '      margin-bottom: 0.5rem;\n'
      html += '    }\n'
      html += '    .slide.default {\n'
      html += '      background-color: #ffffff;\n'
      html += '      color: #333333;\n'
      html += '    }\n'
      html += '    .slide.dark {\n'
      html += '      background-color: #333333;\n'
      html += '      color: #ffffff;\n'
      html += '    }\n'
      html += '    .slide.blue {\n'
      html += '      background-color: #e3f2fd;\n'
      html += '      color: #1976d2;\n'
      html += '    }\n'
      html += '    .slide.green {\n'
      html += '      background-color: #e8f5e8;\n'
      html += '      color: #388e3c;\n'
      html += '    }\n'
      html += '  </style>\n'
      html += '</head>\n'
      html += '<body>\n'
      
      this.slides.forEach(slide => {
        if (slide.level === 0) {
          html += '  <div class="slide ' + this.theme + '">\n'
          html += '    <div class="slide-header">\n'
          html += '      <h1>' + slide.content + '</h1>\n'
          html += '    </div>\n'
          html += '  </div>\n'
        } else {
          html += '  <div class="slide ' + this.theme + '">\n'
          html += '    <div class="slide-content">\n'
          if (slide.level === 1) {
            html += '      <h2>' + slide.content + '</h2>\n'
          } else if (slide.level === 2) {
            html += '      <h3>' + slide.content + '</h3>\n'
          } else {
            html += '      <div class="slide-text">' + slide.content.replace(/\n/g, '<br>') + '</div>\n'
          }
          html += '    </div>\n'
          html += '  </div>\n'
        }
      })
      
      html += '</body>\n'
      html += '</html>\n'
      
      // 创建下载链接
      const blob = new Blob([html], { type: 'text/html' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = (this.pptTitle || 'presentation') + '.html'
      a.click()
      URL.revokeObjectURL(url)
      
      this.$message.success('PPT 导出成功')
    }
  }
}
</script>

