<template>
  <div class="command-reference-tool">
    <el-card>
      <div slot="header">
        <span>命令参考工具</span>
        <el-tag size="small" style="margin-left: 10px">{{ filteredCommands.length }} 个命令</el-tag>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <div class="search-section">
            <el-input
              v-model="searchKeyword"
              placeholder="搜索命令..."
              prefix-icon="el-icon-search"
              clearable
              @input="handleSearch"
            />
            
            <el-select v-model="selectedCategory" placeholder="选择分类" style="margin-top: 10px; width: 100%">
              <el-option-group label="Linux 命令">
                <el-option label="Linux 基础命令" value="linux-basic" />
                <el-option label="Linux 文件命令" value="linux-file" />
                <el-option label="Linux 网络命令" value="linux-network" />
                <el-option label="Linux 系统命令" value="linux-system" />
                <el-option label="Linux 文本处理" value="linux-text" />
                <el-option label="Linux 压缩归档" value="linux-archive" />
                <el-option label="Linux 权限管理" value="linux-perm" />
                <el-option label="Linux 用户管理" value="linux-user" />
                <el-option label="Linux 进程管理" value="linux-process" />
                <el-option label="Linux 磁盘管理" value="linux-disk" />
                <el-option label="Linux 包管理" value="linux-package" />
                <el-option label="Linux 性能工具" value="linux-perf" />
              </el-option-group>
              <el-option-group label="开发工具">
                <el-option label="Git 命令" value="git" />
                <el-option label="Docker 命令" value="docker" />
                <el-option label="Kubernetes 命令" value="k8s" />
                <el-option label="Maven 命令" value="maven" />
                <el-option label="Gradle 命令" value="gradle" />
                <el-option label="NPM / Yarn / PNPM" value="npm" />
                <el-option label="Python 命令" value="python" />
                <el-option label="Go 命令" value="go" />
                <el-option label="Java/JVM 工具" value="java" />
              </el-option-group>
              <el-option-group label="数据库">
                <el-option label="MySQL 命令" value="mysql" />
                <el-option label="PostgreSQL 命令" value="postgresql" />
                <el-option label="MongoDB 命令" value="mongodb" />
                <el-option label="Redis 命令" value="redis" />
                <el-option label="Elasticsearch 命令" value="elasticsearch" />
                <el-option label="Kafka 命令" value="kafka" />
              </el-option-group>
              <el-option-group label="系统服务">
                <el-option label="Nginx 命令" value="nginx" />
                <el-option label="Systemd 命令" value="systemd" />
                <el-option label="Curl / Wget" value="curl" />
                <el-option label="SSH / SCP" value="ssh" />
              </el-option-group>
              <el-option-group label="编辑器/工具">
                <el-option label="Vim 编辑器" value="vim" />
                <el-option label="Screen / Tmux" value="terminal" />
                <el-option label="awk / sed" value="awk-sed" />
              </el-option-group>
            </el-select>

            <div class="command-list">
              <el-empty v-if="filteredCommands.length === 0" description="未找到命令" />
              <el-scrollbar height="500px">
                <div
                  v-for="command in filteredCommands"
                  :key="command.name"
                  class="command-item"
                  @click="selectCommand(command)"
                  :class="{ active: selectedCommand && selectedCommand.name === command.name }"
                >
                  <div class="command-name">{{ command.name }}</div>
                  <div class="command-desc">{{ command.description }}</div>
                </div>
              </el-scrollbar>
            </div>
          </div>
        </el-col>

        <el-col :span="12">
          <div class="command-detail">
            <el-empty v-if="!selectedCommand" description="请选择一个命令" />
            <div v-else class="detail-content">
              <h3>{{ selectedCommand.name }}</h3>
              <p class="description">{{ selectedCommand.description }}</p>
              
              <el-divider content-position="left">语法</el-divider>
              <div class="syntax">
                <code>{{ selectedCommand.syntax }}</code>
              </div>
              
              <el-divider content-position="left">选项</el-divider>
              <el-table :data="selectedCommand.options" size="small" v-if="selectedCommand.options && selectedCommand.options.length > 0">
                <el-table-column prop="option" label="选项" width="120" />
                <el-table-column prop="description" label="描述" />
              </el-table>
              <p v-else class="no-data">无选项信息</p>
              
              <el-divider content-position="left">示例</el-divider>
              <div class="examples" v-if="selectedCommand.examples && selectedCommand.examples.length > 0">
                <div v-for="(example, index) in selectedCommand.examples" :key="index" class="example-item">
                  <div class="example-code"><code>{{ example.code }}</code></div>
                  <div class="example-desc">{{ example.description }}</div>
                </div>
              </div>
              <p v-else class="no-data">无示例信息</p>
            </div>
          </div>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
// 导入命令数据
import commandData from './commands/allCommands.js'

export default {
  name: 'CommandReferenceTool',
  data() {
    return {
      searchKeyword: '',
      selectedCategory: '',
      selectedCommand: null,
      allCommands: commandData
    }
  },
  computed: {
    filteredCommands() {
      let commands = this.allCommands
      
      if (this.selectedCategory) {
        commands = commands.filter(cmd => cmd.category === this.selectedCategory)
      }
      
      if (this.searchKeyword) {
        const keyword = this.searchKeyword.toLowerCase()
        commands = commands.filter(cmd =>
          cmd.name.toLowerCase().includes(keyword) ||
          cmd.description.toLowerCase().includes(keyword)
        )
      }
      
      return commands
    }
  },
  methods: {
    handleSearch() {
      // 搜索逻辑在 computed 中处理
    },
    selectCommand(command) {
      this.selectedCommand = command
    }
  },
  mounted() {
    // 默认选择第一个命令
    if (this.filteredCommands.length > 0) {
      this.selectedCommand = this.filteredCommands[0]
    }
  }
}
</script>

<style scoped>
.command-reference-tool {
  padding: 20px;
}

.search-section {
  margin-bottom: 20px;
}

.command-list {
  margin-top: 15px;
  border: 1px solid #ebeef5;
  border-radius: 4px;
}

.command-item {
  padding: 12px 15px;
  border-bottom: 1px solid #ebeef5;
  cursor: pointer;
  transition: background-color 0.3s;
}

.command-item:last-child {
  border-bottom: none;
}

.command-item:hover,
.command-item.active {
  background-color: #f5f7fa;
}

.command-name {
  font-weight: bold;
  color: #409EFF;
  font-size: 14px;
}

.command-desc {
  font-size: 12px;
  color: #606266;
  margin-top: 4px;
}

.command-detail {
  background: #f5f7fa;
  padding: 20px;
  border-radius: 4px;
  min-height: 500px;
}

.detail-content h3 {
  margin: 0 0 10px 0;
  color: #303133;
}

.detail-content .description {
  color: #606266;
  margin-bottom: 20px;
}

.syntax {
  background: #303133;
  color: #fff;
  padding: 15px;
  border-radius: 4px;
  font-family: 'Courier New', monospace;
  margin-bottom: 20px;
}

.syntax code {
  color: #fff;
  background: transparent;
}

.examples {
  background: #fff;
  padding: 15px;
  border-radius: 4px;
}

.example-item {
  margin-bottom: 15px;
  padding-bottom: 15px;
  border-bottom: 1px dashed #ebeef5;
}

.example-item:last-child {
  margin-bottom: 0;
  padding-bottom: 0;
  border-bottom: none;
}

.example-code {
  background: #f0f2f5;
  padding: 8px 12px;
  border-radius: 4px;
  margin-bottom: 5px;
  font-family: 'Courier New', monospace;
}

.example-code code {
  color: #e83e8c;
  background: transparent;
}

.example-desc {
  color: #909399;
  font-size: 13px;
}

.no-data {
  color: #909399;
  font-style: italic;
}
</style>
