<script>
export default {
  name: 'UnitTool',
  data() {
    return {
      activeTab: 'length',
      length: {
        input: 1,
        from: 'm',
        to: 'km',
        result: ''
      },
      weight: {
        input: 1,
        from: 'kg',
        to: 'g',
        result: ''
      },
      temperature: {
        input: 25,
        from: 'c',
        to: 'f',
        result: ''
      },
      area: {
        input: 1,
        from: 'm2',
        to: 'km2',
        result: ''
      },
      volume: {
        input: 1,
        from: 'l',
        to: 'ml',
        result: ''
      },
      time: {
        input: 1,
        from: 'h',
        to: 'min',
        result: ''
      }
    }
  },
  mounted() {
    this.convertLength()
    this.convertWeight()
    this.convertTemperature()
    this.convertArea()
    this.convertVolume()
    this.convertTime()
  },
  methods: {
    convertLength() {
      const { input, from, to } = this.length
      
      const toMeters = {
        m: 1,
        km: 1000,
        cm: 0.01,
        mm: 0.001,
        um: 0.000001,
        nm: 0.000000001,
        mi: 1609.344,
        yd: 0.9144,
        ft: 0.3048,
        in: 0.0254,
        nmi: 1852
      }
      
      const meters = input * toMeters[from]
      const result = meters / toMeters[to]
      
      this.length.result = result.toFixed(6)
    },
    convertWeight() {
      const { input, from, to } = this.weight
      
      const toKilograms = {
        kg: 1,
        g: 0.001,
        mg: 0.000001,
        t: 1000,
        lb: 0.453592,
        oz: 0.0283495,
        ct: 0.0002
      }
      
      const kilograms = input * toKilograms[from]
      const result = kilograms / toKilograms[to]
      
      this.weight.result = result.toFixed(6)
    },
    convertTemperature() {
      const { input, from, to } = this.temperature
      let celsius
      
      if (from === 'c') {
        celsius = input
      } else if (from === 'f') {
        celsius = (input - 32) * 5 / 9
      } else if (from === 'k') {
        celsius = input - 273.15
      }
      
      let result
      if (to === 'c') {
        result = celsius
      } else if (to === 'f') {
        result = celsius * 9 / 5 + 32
      } else if (to === 'k') {
        result = celsius + 273.15
      }
      
      this.temperature.result = result.toFixed(2)
    },
    convertArea() {
      const { input, from, to } = this.area
      
      const toSquareMeters = {
        m2: 1,
        km2: 1000000,
        cm2: 0.0001,
        mm2: 0.000001,
        ha: 10000,
        ac: 4046.86,
        ft2: 0.092903,
        in2: 0.00064516
      }
      
      const squareMeters = input * toSquareMeters[from]
      const result = squareMeters / toSquareMeters[to]
      
      this.area.result = result.toFixed(6)
    },
    convertVolume() {
      const { input, from, to } = this.volume
      
      const toLiters = {
        m3: 1000,
        l: 1,
        ml: 0.001,
        cm3: 0.001,
        mm3: 0.000001,
        gal: 3.78541,
        qt: 0.946353,
        pt: 0.473176,
        cup: 0.236588,
        floz: 0.0295735
      }
      
      const liters = input * toLiters[from]
      const result = liters / toLiters[to]
      
      this.volume.result = result.toFixed(6)
    },
    convertTime() {
      const { input, from, to } = this.time
      
      const toSeconds = {
        s: 1,
        ms: 0.001,
        us: 0.000001,
        ns: 0.000000001,
        min: 60,
        h: 3600,
        d: 86400,
        w: 604800,
        y: 31536000
      }
      
      const seconds = input * toSeconds[from]
      const result = seconds / toSeconds[to]
      
      this.time.result = result.toFixed(6)
    },
    clearAll() {
      this.length = {
        input: 1,
        from: 'm',
        to: 'km',
        result: ''
      }
      this.weight = {
        input: 1,
        from: 'kg',
        to: 'g',
        result: ''
      }
      this.temperature = {
        input: 25,
        from: 'c',
        to: 'f',
        result: ''
      }
      this.area = {
        input: 1,
        from: 'm2',
        to: 'km2',
        result: ''
      }
      this.volume = {
        input: 1,
        from: 'l',
        to: 'ml',
        result: ''
      }
      this.time = {
        input: 1,
        from: 'h',
        to: 'min',
        result: ''
      }
      
      this.convertLength()
      this.convertWeight()
      this.convertTemperature()
      this.convertArea()
      this.convertVolume()
      this.convertTime()
    }
  }
}
</script>

