<template>
  <div class="css-converter-tool">
    <el-card>
      <div slot="header">
        <span>CSS 转换器</span>
        <el-button style="float: right; padding: 3px 0" type="text" @click="loadExample">加载示例</el-button>
      </div>

      <el-form :model="config" label-width="120px">
        <el-form-item label="转换方向">
          <el-radio-group v-model="config.direction">
            <el-radio-button label="css-to-scss">CSS → SCSS</el-radio-button>
            <el-radio-button label="css-to-less">CSS → Less</el-radio-button>
            <el-radio-button label="scss-to-css">SCSS → CSS</el-radio-button>
            <el-radio-button label="less-to-css">Less → CSS</el-radio-button>
          </el-radio-group>
        </el-form-item>
      </el-form>

      <el-row :gutter="20">
        <el-col :span="12">
          <div class="input-section">
            <div class="section-header">
              <span class="section-title">{{ inputLabel }}</span>
              <div class="section-actions">
                <el-button type="text" size="small" @click="formatInput">格式化</el-button>
                <el-button type="text" size="small" @click="clearInput">清空</el-button>
              </div>
            </div>
            <el-input
              v-model="input"
              type="textarea"
              :rows="20"
              :placeholder="inputPlaceholder"
            />
          </div>
        </el-col>

        <el-col :span="12">
          <div class="output-section">
            <div class="section-header">
              <span class="section-title">{{ outputLabel }}</span>
              <div class="section-actions">
                <el-button type="text" size="small" @click="copyOutput">复制</el-button>
                <el-button type="text" size="small" @click="downloadOutput">下载</el-button>
              </div>
            </div>
            <el-input
              v-model="output"
              type="textarea"
              :rows="20"
              readonly
              :placeholder="outputPlaceholder"
            />
          </div>
        </el-col>
      </el-row>

      <div class="action-buttons">
        <el-button type="primary" @click="convert">转换</el-button>
        <el-button @click="clear">全部清空</el-button>
      </div>

      <el-divider>转换选项</el-divider>

      <el-form :model="options" label-width="180px">
        <el-row :gutter="20">
          <el-col :span="8">
            <el-form-item label="嵌套层级">
              <el-input-number v-model="options.nestingLevel" :min="1" :max="10" />
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="使用变量">
              <el-switch v-model="options.useVariables" />
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="添加 Mixins">
              <el-switch v-model="options.addMixins" />
            </el-form-item>
          </el-col>
        </el-row>
        <el-row :gutter="20">
          <el-col :span="8">
            <el-form-item label="压缩输出">
              <el-switch v-model="options.minify" />
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="添加浏览器前缀">
              <el-switch v-model="options.addPrefixes" />
            </el-form-item>
          </el-col>
          <el-col :span="8">
            <el-form-item label="排序属性">
              <el-switch v-model="options.sortProperties" />
            </el-form-item>
          </el-col>
        </el-row>
      </el-form>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'CssConverterTool',
  data() {
    return {
      config: {
        direction: 'css-to-scss'
      },
      input: '',
      output: '',
      options: {
        nestingLevel: 5,
        useVariables: true,
        addMixins: false,
        minify: false,
        addPrefixes: false,
        sortProperties: false
      }
    }
  },
  computed: {
    inputLabel() {
      const labels = {
        'css-to-scss': 'CSS',
        'css-to-less': 'CSS',
        'scss-to-css': 'SCSS',
        'less-to-css': 'Less'
      }
      return labels[this.config.direction]
    },
    outputLabel() {
      const labels = {
        'css-to-scss': 'SCSS',
        'css-to-less': 'Less',
        'scss-to-css': 'CSS',
        'less-to-css': 'CSS'
      }
      return labels[this.config.direction]
    },
    inputPlaceholder() {
      return `粘贴 ${this.inputLabel} 代码...`
    },
    outputPlaceholder() {
      return '转换结果将显示在这里...'
    }
  },
  methods: {
    convert() {
      if (!this.input) {
        this.$message.warning('请输入需要转换的代码')
        return
      }

      try {
        switch (this.config.direction) {
          case 'css-to-scss':
            this.output = this.cssToScss(this.input)
            break
          case 'css-to-less':
            this.output = this.cssToLess(this.input)
            break
          case 'scss-to-css':
            this.output = this.scssToCss(this.input)
            break
          case 'less-to-css':
            this.output = this.lessToCss(this.input)
            break
        }
      } catch (error) {
        this.$message.error('转换失败: ' + error.message)
      }
    },
    cssToScss(css) {
      let scss = css
      const indent = '  '
      
      // Parse CSS rules
      const rules = this.parseCssRules(css)
      
      // Group related selectors
      const grouped = this.groupSelectors(rules)
      
      // Generate SCSS with nesting
      let result = ''
      
      // Add variables for common values
      if (this.options.useVariables) {
        const variables = this.extractVariables(rules)
        if (Object.keys(variables).length > 0) {
          result += '// Variables\n'
          Object.entries(variables).forEach(([name, value]) => {
            result += `$${name}: ${value};\n`
          })
          result += '\n'
        }
      }
      
      // Generate nested SCSS
      Object.entries(grouped).forEach(([baseSelector, nestedRules]) => {
        result += `${baseSelector} {\n`
        
        // Add base properties
        const baseRule = nestedRules.find(r => r.selector === baseSelector)
        if (baseRule) {
          baseRule.properties.forEach(prop => {
            if (this.options.useVariables) {
              prop = this.replaceWithVariable(prop)
            }
            result += `${indent}${prop}\n`
          })
        }
        
        // Add nested selectors
        nestedRules.filter(r => r.selector !== baseSelector).forEach(rule => {
          const nestedSelector = rule.selector.replace(baseSelector, '').trim()
          result += `${indent}${nestedSelector} {\n`
          rule.properties.forEach(prop => {
            if (this.options.useVariables) {
              prop = this.replaceWithVariable(prop)
            }
            result += `${indent}${indent}${prop}\n`
          })
          result += `${indent}}\n`
        })
        
        result += '}\n\n'
      })
      
      return this.options.minify ? this.minifyCss(result) : result.trim()
    },
    cssToLess(css) {
      // Similar to SCSS but with Less syntax
      let less = css
      
      // Parse CSS rules
      const rules = this.parseCssRules(css)
      const grouped = this.groupSelectors(rules)
      
      let result = ''
      
      // Add variables
      if (this.options.useVariables) {
        const variables = this.extractVariables(rules)
        if (Object.keys(variables).length > 0) {
          result += '// Variables\n'
          Object.entries(variables).forEach(([name, value]) => {
            result += `@${name}: ${value};\n`
          })
          result += '\n'
        }
      }
      
      // Generate nested Less
      Object.entries(grouped).forEach(([baseSelector, nestedRules]) => {
        result += `${baseSelector} {\n`
        
        const baseRule = nestedRules.find(r => r.selector === baseSelector)
        if (baseRule) {
          baseRule.properties.forEach(prop => {
            if (this.options.useVariables) {
              prop = prop.replace(/:\s*/, ': @')
            }
            result += `  ${prop}\n`
          })
        }
        
        nestedRules.filter(r => r.selector !== baseSelector).forEach(rule => {
          const nestedSelector = rule.selector.replace(baseSelector, '').trim()
          result += `  ${nestedSelector} {\n`
          rule.properties.forEach(prop => {
            result += `    ${prop}\n`
          })
          result += `  }\n`
        })
        
        result += '}\n\n'
      })
      
      return this.options.minify ? this.minifyCss(result) : result.trim()
    },
    scssToCss(scss) {
      // Flatten nested SCSS to CSS
      let css = scss
      
      // Remove variables (simplified - just remove lines starting with $)
      css = css.replace(/\$[\w-]+:\s*[^;]+;/g, '')
      
      // Remove mixins
      css = css.replace(/@mixin[\s\S]*?^}/gm, '')
      css = css.replace(/@include\s+\w+\([^)]*\);/g, '')
      
      // Flatten nesting
      const rules = this.parseScssRules(scss)
      let result = ''
      
      rules.forEach(rule => {
        result += `${rule.selector} {\n`
        rule.properties.forEach(prop => {
          // Replace variables with their values (simplified)
          prop = prop.replace(/\$[\w-]+/g, 'var(--$&)')
          result += `  ${prop}\n`
        })
        result += '}\n\n'
      })
      
      return this.options.minify ? this.minifyCss(result) : result.trim()
    },
    lessToCss(less) {
      // Similar to SCSS to CSS
      let css = less
      
      // Remove variables
      css = css.replace(/@[\w-]+:\s*[^;]+;/g, '')
      
      // Flatten nesting
      const rules = this.parseLessRules(less)
      let result = ''
      
      rules.forEach(rule => {
        result += `${rule.selector} {\n`
        rule.properties.forEach(prop => {
          prop = prop.replace(/@[\w-]+/g, 'var(--$&)')
          result += `  ${prop}\n`
        })
        result += '}\n\n'
      })
      
      return this.options.minify ? this.minifyCss(result) : result.trim()
    },
    parseCssRules(css) {
      const rules = []
      const regex = /([^{]+)\{([^}]*)\}/g
      let match
      
      while ((match = regex.exec(css)) !== null) {
        const selector = match[1].trim()
        const properties = match[2].trim().split(';').filter(p => p.trim()).map(p => p.trim() + ';')
        rules.push({ selector, properties })
      }
      
      return rules
    },
    parseScssRules(scss) {
      // Simplified SCSS parser
      return this.parseCssRules(scss)
    },
    parseLessRules(less) {
      // Simplified Less parser
      return this.parseCssRules(less)
    },
    groupSelectors(rules) {
      const grouped = {}
      
      rules.forEach(rule => {
        const baseSelector = rule.selector.split(/[:\s>+~]/)[0]
        if (!grouped[baseSelector]) {
          grouped[baseSelector] = []
        }
        grouped[baseSelector].push(rule)
      })
      
      return grouped
    },
    extractVariables(rules) {
      const variables = {}
      const valueCount = {}
      
      rules.forEach(rule => {
        rule.properties.forEach(prop => {
          const match = prop.match(/:\s*(.+);/)
          if (match) {
            const value = match[1].trim()
            valueCount[value] = (valueCount[value] || 0) + 1
            if (valueCount[value] >= 2) {
              const varName = this.valueToVariableName(value)
              variables[varName] = value
            }
          }
        })
      })
      
      return variables
    },
    valueToVariableName(value) {
      // Generate variable name from value
      if (value.startsWith('#')) {
        return 'color-' + value.slice(1)
      }
      if (value.includes('px')) {
        return 'size-' + value.replace(/\D/g, '')
      }
      return 'var-' + Math.random().toString(36).substr(2, 5)
    },
    replaceWithVariable(prop) {
      // Simplified variable replacement
      return prop
    },
    minifyCss(css) {
      return css
        .replace(/\/\*[\s\S]*?\*\//g, '')
        .replace(/\s+/g, ' ')
        .replace(/\s*([{}:;,])\s*/g, '$1')
        .replace(/;\s*}/g, '}')
        .trim()
    },
    formatInput() {
      if (!this.input) return
      // Simple CSS formatting
      this.input = this.input
        .replace(/\s*\{\s*/g, ' {\n  ')
        .replace(/;\s*/g, ';\n  ')
        .replace(/\s*\}\s*/g, '\n}\n')
        .replace(/\n\s*\n/g, '\n')
        .trim()
    },
    copyOutput() {
      if (!this.output) {
        this.$message.warning('没有可复制的内容')
        return
      }
      navigator.clipboard.writeText(this.output).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    },
    downloadOutput() {
      if (!this.output) {
        this.$message.warning('没有可下载的内容')
        return
      }
      const extensions = {
        'css-to-scss': 'scss',
        'css-to-less': 'less',
        'scss-to-css': 'css',
        'less-to-css': 'css'
      }
      const blob = new Blob([this.output], { type: 'text/plain' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = `converted.${extensions[this.config.direction]}`
      link.click()
      URL.revokeObjectURL(url)
    },
    clearInput() {
      this.input = ''
    },
    clear() {
      this.input = ''
      this.output = ''
    },
    loadExample() {
      this.config.direction = 'css-to-scss'
      this.input = `.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
}

.container .header {
  background: #333;
  color: #fff;
  padding: 10px;
}

.container .header h1 {
  font-size: 24px;
  margin: 0;
}

.container .content {
  background: #f5f5f5;
  padding: 20px;
}

.button {
  background: #007bff;
  color: #fff;
  padding: 10px 20px;
  border: none;
  border-radius: 4px;
}

.button:hover {
  background: #0056b3;
}`
      this.convert()
    }
  }
}
</script>

<style scoped>
.css-converter-tool {
  padding: 20px;
}

.input-section, .output-section {
  height: 100%;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}

.section-title {
  font-weight: bold;
  color: #606266;
}

.section-actions {
  display: flex;
  gap: 10px;
}

.action-buttons {
  text-align: center;
  margin: 20px 0;
}
</style>
