<template>
  <div class="loan-tool">
    <el-card>
      <div slot="header">
        <span>贷款利息计算器</span>
        <el-button style="float: right; padding: 3px 0" type="text" @click="loadExample">加载示例</el-button>
      </div>

      <el-row :gutter="20">
        <el-col :span="12">
          <el-form :model="loanForm" label-width="120px">
            <el-form-item label="贷款金额">
              <el-input v-model="loanForm.amount" placeholder="输入贷款金额">
                <template slot="append">元</template>
              </el-input>
            </el-form-item>

            <el-form-item label="贷款期限">
              <el-input-number v-model="loanForm.years" :min="1" :max="30" style="width: 120px" />
              <span style="margin-left: 10px">年</span>
              <span style="margin-left: 20px; color: #909399">({{ loanForm.years * 12 }} 个月)</span>
            </el-form-item>

            <el-form-item label="年利率">
              <el-input v-model="loanForm.rate" placeholder="输入年利率">
                <template slot="append">%</template>
              </el-input>
            </el-form-item>

            <el-form-item label="还款方式">
              <el-radio-group v-model="loanForm.method">
                <el-radio-button label="equal_payment">等额本息</el-radio-button>
                <el-radio-button label="equal_principal">等额本金</el-radio-button>
              </el-radio-group>
            </el-form-item>

            <el-form-item>
              <el-button type="primary" @click="calculateLoan">计算</el-button>
              <el-button @click="clear">清空</el-button>
            </el-form-item>
          </el-form>
        </el-col>

        <el-col :span="12" v-if="result">
          <div class="result-summary">
            <h4>计算结果</h4>
            <el-row :gutter="20">
              <el-col :span="12">
                <div class="summary-item">
                  <div class="summary-label">每月还款</div>
                  <div class="summary-value highlight">{{ formatCurrency(result.monthlyPayment) }}</div>
                </div>
              </el-col>
              <el-col :span="12" v-if="loanForm.method === 'equal_principal'">
                <div class="summary-item">
                  <div class="summary-label">首月还款</div>
                  <div class="summary-value">{{ formatCurrency(result.firstMonthPayment) }}</div>
                </div>
              </el-col>
              <el-col :span="12">
                <div class="summary-item">
                  <div class="summary-label">还款总额</div>
                  <div class="summary-value">{{ formatCurrency(result.totalPayment) }}</div>
                </div>
              </el-col>
              <el-col :span="12">
                <div class="summary-item">
                  <div class="summary-label">支付利息</div>
                  <div class="summary-value interest">{{ formatCurrency(result.totalInterest) }}</div>
                </div>
              </el-col>
            </el-row>
          </div>
        </el-col>
      </el-row>

      <el-divider v-if="result">还款计划表</el-divider>

      <div v-if="result" class="schedule-section">
        <el-table :data="result.schedule" height="400" border>
          <el-table-column prop="month" label="期数" width="80" />
          <el-table-column prop="payment" label="月供" width="120">
            <template slot-scope="scope">
              {{ formatCurrency(scope.row.payment) }}
            </template>
          </el-table-column>
          <el-table-column prop="principal" label="本金" width="120">
            <template slot-scope="scope">
              {{ formatCurrency(scope.row.principal) }}
            </template>
          </el-table-column>
          <el-table-column prop="interest" label="利息" width="120">
            <template slot-scope="scope">
              {{ formatCurrency(scope.row.interest) }}
            </template>
          </el-table-column>
          <el-table-column prop="remaining" label="剩余本金" width="120">
            <template slot-scope="scope">
              {{ formatCurrency(scope.row.remaining) }}
            </template>
          </el-table-column>
          <el-table-column prop="cumulativeInterest" label="累计利息" width="120">
            <template slot-scope="scope">
              {{ formatCurrency(scope.row.cumulativeInterest) }}
            </template>
          </el-table-column>
        </el-table>

        <div class="export-buttons">
          <el-button type="primary" size="small" @click="exportSchedule">导出还款计划</el-button>
        </div>
      </div>

      <el-divider>利率参考</el-divider>

      <el-table :data="rateReference" border size="small">
        <el-table-column prop="type" label="贷款类型" />
        <el-table-column prop="rate" label="基准利率" width="150">
          <template slot-scope="scope">
            {{ scope.row.rate }}%
          </template>
        </el-table-column>
        <el-table-column prop="description" label="说明" />
      </el-table>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'LoanTool',
  data() {
    return {
      loanForm: {
        amount: '',
        years: 20,
        rate: '',
        method: 'equal_payment'
      },
      result: null,
      rateReference: [
        { type: '商业贷款(1-5年)', rate: '4.75', description: '短期商业贷款基准利率' },
        { type: '商业贷款(5-30年)', rate: '4.90', description: '长期商业贷款基准利率' },
        { type: '公积金贷款(1-5年)', rate: '2.75', description: '短期公积金贷款基准利率' },
        { type: '公积金贷款(5-30年)', rate: '3.25', description: '长期公积金贷款基准利率' }
      ]
    }
  },
  methods: {
    calculateLoan() {
      const amount = parseFloat(this.loanForm.amount)
      const years = this.loanForm.years
      const rate = parseFloat(this.loanForm.rate) / 100
      const months = years * 12
      const monthlyRate = rate / 12

      if (!amount || !rate) {
        this.$message.warning('请输入完整的贷款信息')
        return
      }

      let schedule = []
      let totalPayment = 0
      let totalInterest = 0

      if (this.loanForm.method === 'equal_payment') {
        // 等额本息
        const monthlyPayment = amount * monthlyRate * Math.pow(1 + monthlyRate, months) / 
                              (Math.pow(1 + monthlyRate, months) - 1)
        
        let remaining = amount
        let cumulativeInterest = 0
        
        for (let i = 1; i <= months; i++) {
          const interest = remaining * monthlyRate
          const principal = monthlyPayment - interest
          remaining -= principal
          cumulativeInterest += interest
          
          schedule.push({
            month: i,
            payment: monthlyPayment,
            principal: principal,
            interest: interest,
            remaining: Math.max(0, remaining),
            cumulativeInterest: cumulativeInterest
          })
          
          totalPayment += monthlyPayment
          totalInterest += interest
        }

        this.result = {
          monthlyPayment: monthlyPayment,
          totalPayment: totalPayment,
          totalInterest: totalInterest,
          schedule: schedule
        }
      } else {
        // 等额本金
        const monthlyPrincipal = amount / months
        let remaining = amount
        let cumulativeInterest = 0
        let firstMonthPayment = 0
        
        for (let i = 1; i <= months; i++) {
          const interest = remaining * monthlyRate
          const payment = monthlyPrincipal + interest
          remaining -= monthlyPrincipal
          cumulativeInterest += interest
          
          if (i === 1) {
            firstMonthPayment = payment
          }
          
          schedule.push({
            month: i,
            payment: payment,
            principal: monthlyPrincipal,
            interest: interest,
            remaining: Math.max(0, remaining),
            cumulativeInterest: cumulativeInterest
          })
          
          totalPayment += payment
          totalInterest += interest
        }

        this.result = {
          monthlyPayment: monthlyPrincipal,
          firstMonthPayment: firstMonthPayment,
          totalPayment: totalPayment,
          totalInterest: totalInterest,
          schedule: schedule
        }
      }
    },
    formatCurrency(value) {
      return '¥' + value.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',')
    },
    exportSchedule() {
      if (!this.result) return
      
      const headers = ['期数', '月供', '本金', '利息', '剩余本金', '累计利息']
      const rows = this.result.schedule.map(item => [
        item.month,
        item.payment.toFixed(2),
        item.principal.toFixed(2),
        item.interest.toFixed(2),
        item.remaining.toFixed(2),
        item.cumulativeInterest.toFixed(2)
      ])
      
      const csv = [headers.join(','), ...rows.map(r => r.join(','))].join('\n')
      const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8;' })
      const link = document.createElement('a')
      link.href = URL.createObjectURL(blob)
      link.download = '还款计划表.csv'
      link.click()
    },
    clear() {
      this.loanForm = {
        amount: '',
        years: 20,
        rate: '',
        method: 'equal_payment'
      }
      this.result = null
    },
    loadExample() {
      this.loanForm = {
        amount: '1000000',
        years: 20,
        rate: '4.9',
        method: 'equal_payment'
      }
      this.calculateLoan()
    }
  }
}
</script>

<style scoped>
.loan-tool {
  padding: 20px;
}

.result-summary {
  padding: 20px;
  background: #f5f7fa;
  border-radius: 4px;
}

.result-summary h4 {
  margin-top: 0;
  margin-bottom: 20px;
  color: #303133;
}

.summary-item {
  text-align: center;
  padding: 15px;
  background: #fff;
  border-radius: 4px;
  margin-bottom: 10px;
}

.summary-label {
  font-size: 12px;
  color: #909399;
  margin-bottom: 8px;
}

.summary-value {
  font-size: 18px;
  font-weight: bold;
  color: #606266;
}

.summary-value.highlight {
  color: #409eff;
  font-size: 24px;
}

.summary-value.interest {
  color: #f56c6c;
}

.schedule-section {
  margin-top: 20px;
}

.export-buttons {
  text-align: center;
  margin-top: 15px;
}
</style>
