<template>
  <div class="tool-container">
    <el-card class="tool-card">
      <div slot="header">
        <span>Base64 编解码</span>
        <el-button-group class="header-actions">
          <el-button size="small" @click="clearAll">清空</el-button>
          <el-button size="small" type="primary" @click="showFileDialog = true">文件转Base64</el-button>
        </el-button-group>
      </div>
      
      <el-row :gutter="20">
        <el-col :span="11">
          <div class="input-section">
            <div class="section-header">
              <span>原文</span>
              <el-tag size="mini" type="primary">输入或输出</el-tag>
            </div>
            <el-input
              v-model="inputText"
              type="textarea"
              :rows="12"
              placeholder="请输入原文或 Base64 编码"
            />
          </div>
        </el-col>
        
        <el-col :span="2" class="actions-col">
          <div class="action-buttons">
            <el-button type="primary" circle @click="encode" title="原文 → Base64">
              <i class="el-icon-right"></i>
            </el-button>
            <span class="action-label">编码</span>
            <el-button type="success" circle @click="decode" title="Base64 → 原文">
              <i class="el-icon-back"></i>
            </el-button>
            <span class="action-label">解码</span>
          </div>
        </el-col>
        
        <el-col :span="11">
          <div class="output-section">
            <div class="section-header">
              <span>Base64</span>
              <el-tag size="mini" type="success">输入或输出</el-tag>
            </div>
            <el-input
              v-model="outputText"
              type="textarea"
              :rows="12"
              placeholder="请输入 Base64 或查看编码结果"
            />
          </div>
        </el-col>
      </el-row>
    </el-card>

    <el-dialog title="文件转 Base64" :visible.sync="showFileDialog" width="500px">
      <el-upload
        drag
        action=""
        :auto-upload="false"
        :on-change="handleDialogFileChange"
        :show-file-list="false"
      >
        <i class="el-icon-upload"></i>
        <div class="el-upload__text">将文件拖到此处，或<em>点击上传</em></div>
      </el-upload>
      <div v-if="dialogFileName" class="dialog-file-info">
        <p>文件名: {{ dialogFileName }}</p>
        <p>大小: {{ dialogFileSize }}</p>
      </div>
      <div slot="footer">
        <el-button @click="showFileDialog = false">取消</el-button>
        <el-button type="primary" @click="convertFileToBase64" :disabled="!dialogFile">转换</el-button>
      </div>
    </el-dialog>
  </div>
</template>

<script>
export default {
  name: 'Base64Tool',
  data() {
    return {
      inputText: '',
      outputText: '',
      showFileDialog: false,
      dialogFile: null,
      dialogFileName: '',
      dialogFileSize: ''
    }
  },
  methods: {
    encode() {
      if (!this.inputText) {
        this.$message.warning('请输入要编码的内容')
        return
      }
      try {
        this.outputText = btoa(unescape(encodeURIComponent(this.inputText)))
        this.$message.success('编码成功')
      } catch (e) {
        this.$message.error('编码失败: ' + e.message)
      }
    },
    decode() {
      const text = this.outputText || this.inputText
      if (!text) {
        this.$message.warning('请输入要解码的 Base64 内容')
        return
      }
      try {
        const decoded = decodeURIComponent(escape(atob(text)))
        if (this.outputText) {
          this.inputText = decoded
        } else {
          this.outputText = decoded
        }
        this.$message.success('解码成功')
      } catch (e) {
        this.$message.error('解码失败: 无效的 Base64 字符串')
      }
    },
    clearAll() {
      this.inputText = ''
      this.outputText = ''
    },
    handleDialogFileChange(file) {
      this.dialogFile = file.raw
      this.dialogFileName = file.name
      this.dialogFileSize = this.formatFileSize(file.size)
    },
    formatFileSize(size) {
      if (size < 1024) return size + ' B'
      if (size < 1024 * 1024) return (size / 1024).toFixed(2) + ' KB'
      return (size / (1024 * 1024)).toFixed(2) + ' MB'
    },
    convertFileToBase64() {
      if (!this.dialogFile) return
      this.readFileAsBase64(this.dialogFile).then(base64 => {
        this.inputType = 'text'
        this.inputText = base64
        this.outputText = ''
        this.showFileDialog = false
        this.dialogFile = null
        this.dialogFileName = ''
        this.$message.success('文件已转换为 Base64')
      })
    }
  }
}
</script>

<style lang="scss" scoped>
.tool-container {
  .tool-card {
    .header-actions {
      float: right;
    }
  }

  .input-section, .output-section {
    .section-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
      font-weight: bold;
    }
  }

  .file-input-area {
    .file-info {
      margin-top: 10px;
      display: flex;
      align-items: center;
      gap: 10px;
    }
  }

  .actions-col {
    display: flex;
    align-items: center;
    justify-content: center;

    .action-buttons {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 10px;

      .action-label {
        font-size: 12px;
        color: #606266;
        margin-bottom: 10px;
      }
    }
  }

  .dialog-file-info {
    margin-top: 20px;
    padding: 10px;
    background: #f5f7fa;
    border-radius: 4px;
  }
}
</style>
