<template>
  <div class="code-snippet-tool">
    <el-card>
      <div slot="header">
        <span>代码片段管理</span>
      </div>

      <el-row :gutter="20">
        <el-col :span="8">
          <div class="snippet-list-header">
            <span>我的片段</span>
            <el-button type="primary" size="small" @click="showAddDialog">
              <i class="el-icon-plus"></i> 新建
            </el-button>
          </div>
          <el-input
            v-model="searchKeyword"
            placeholder="搜索片段..."
            prefix-icon="el-icon-search"
            size="small"
            style="margin-bottom: 10px"
          />
          <div class="snippet-list">
            <div
              v-for="snippet in filteredSnippets"
              :key="snippet.id"
              class="snippet-item"
              :class="{ active: selectedSnippet && selectedSnippet.id === snippet.id }"
              @click="selectSnippet(snippet)"
            >
              <div class="snippet-title">{{ snippet.title }}</div>
              <div class="snippet-meta">
                <el-tag size="mini" :type="getTagType(snippet.language)">{{ snippet.language }}</el-tag>
                <span class="snippet-time">{{ snippet.updatedAt }}</span>
              </div>
            </div>
            <el-empty v-if="filteredSnippets.length === 0" description="暂无片段" />
          </div>
        </el-col>

        <el-col :span="16">
          <div v-if="selectedSnippet" class="snippet-detail">
            <div class="detail-header">
              <h3>{{ selectedSnippet.title }}</h3>
              <div class="detail-actions">
                <el-button type="text" @click="copyCode">复制代码</el-button>
                <el-button type="text" @click="editSnippet">编辑</el-button>
                <el-button type="text" @click="deleteSnippet" style="color: #f56c6c">删除</el-button>
              </div>
            </div>
            <div class="detail-info">
              <el-tag size="small" :type="getTagType(selectedSnippet.language)">{{ selectedSnippet.language }}</el-tag>
              <span class="detail-time">更新于 {{ selectedSnippet.updatedAt }}</span>
            </div>
            <div class="detail-description">{{ selectedSnippet.description }}</div>
            <el-input
              type="textarea"
              :rows="15"
              :value="selectedSnippet.code"
              readonly
              class="code-area"
            />
          </div>
          <el-empty v-else description="请选择一个代码片段" />
        </el-col>
      </el-row>
    </el-card>

    <el-dialog :title="isEditing ? '编辑片段' : '新建片段'" :visible.sync="dialogVisible" width="600px">
      <el-form :model="form" label-width="80px">
        <el-form-item label="标题">
          <el-input v-model="form.title" placeholder="片段标题" />
        </el-form-item>
        <el-form-item label="语言">
          <el-select v-model="form.language" placeholder="选择语言" style="width: 100%">
            <el-option label="JavaScript" value="JavaScript" />
            <el-option label="TypeScript" value="TypeScript" />
            <el-option label="Java" value="Java" />
            <el-option label="Python" value="Python" />
            <el-option label="HTML" value="HTML" />
            <el-option label="CSS" value="CSS" />
            <el-option label="SQL" value="SQL" />
            <el-option label="Shell" value="Shell" />
            <el-option label="其他" value="Other" />
          </el-select>
        </el-form-item>
        <el-form-item label="描述">
          <el-input v-model="form.description" type="textarea" :rows="2" placeholder="片段描述" />
        </el-form-item>
        <el-form-item label="代码">
          <el-input v-model="form.code" type="textarea" :rows="10" placeholder="输入代码..." />
        </el-form-item>
      </el-form>
      <div slot="footer">
        <el-button @click="dialogVisible = false">取消</el-button>
        <el-button type="primary" @click="saveSnippet">保存</el-button>
      </div>
    </el-dialog>
  </div>
</template>

<script>
export default {
  name: 'CodeSnippetTool',
  data() {
    return {
      snippets: [],
      selectedSnippet: null,
      searchKeyword: '',
      dialogVisible: false,
      isEditing: false,
      form: {
        id: null,
        title: '',
        language: 'JavaScript',
        description: '',
        code: ''
      }
    }
  },
  computed: {
    filteredSnippets() {
      if (!this.searchKeyword) return this.snippets
      const keyword = this.searchKeyword.toLowerCase()
      return this.snippets.filter(s => 
        s.title.toLowerCase().includes(keyword) ||
        s.description.toLowerCase().includes(keyword) ||
        s.code.toLowerCase().includes(keyword)
      )
    }
  },
  created() {
    this.loadSnippets()
  },
  methods: {
    loadSnippets() {
      const saved = localStorage.getItem('codeSnippets')
      if (saved) {
        this.snippets = JSON.parse(saved)
      } else {
        this.snippets = [
          {
            id: 1,
            title: '防抖函数',
            language: 'JavaScript',
            description: '防止函数频繁调用，在指定时间后执行',
            code: `function debounce(fn, delay = 300) {
  let timer = null;
  return function(...args) {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      fn.apply(this, args);
    }, delay);
  };
}`,
            updatedAt: new Date().toLocaleDateString()
          },
          {
            id: 2,
            title: '节流函数',
            language: 'JavaScript',
            description: '限制函数在指定时间内只能执行一次',
            code: `function throttle(fn, delay = 300) {
  let lastTime = 0;
  return function(...args) {
    const now = Date.now();
    if (now - lastTime >= delay) {
      fn.apply(this, args);
      lastTime = now;
    }
  };
}`,
            updatedAt: new Date().toLocaleDateString()
          },
          {
            id: 3,
            title: '深拷贝',
            language: 'JavaScript',
            description: '递归实现对象的深拷贝',
            code: `function deepClone(obj) {
  if (obj === null || typeof obj !== 'object') {
    return obj;
  }
  if (obj instanceof Date) {
    return new Date(obj);
  }
  if (obj instanceof Array) {
    return obj.map(item => deepClone(item));
  }
  if (obj instanceof Object) {
    const copy = {};
    for (const key in obj) {
      if (obj.hasOwnProperty(key)) {
        copy[key] = deepClone(obj[key]);
      }
    }
    return copy;
  }
}`,
            updatedAt: new Date().toLocaleDateString()
          }
        ]
      }
    },
    saveToStorage() {
      localStorage.setItem('codeSnippets', JSON.stringify(this.snippets))
    },
    getTagType(language) {
      const types = {
        'JavaScript': 'warning',
        'TypeScript': 'primary',
        'Java': 'danger',
        'Python': 'success',
        'HTML': 'info',
        'CSS': 'info',
        'SQL': 'danger',
        'Shell': 'success'
      }
      return types[language] || ''
    },
    selectSnippet(snippet) {
      this.selectedSnippet = snippet
    },
    showAddDialog() {
      this.isEditing = false
      this.form = {
        id: null,
        title: '',
        language: 'JavaScript',
        description: '',
        code: ''
      }
      this.dialogVisible = true
    },
    editSnippet() {
      this.isEditing = true
      this.form = { ...this.selectedSnippet }
      this.dialogVisible = true
    },
    saveSnippet() {
      if (!this.form.title || !this.form.code) {
        this.$message.warning('请填写标题和代码')
        return
      }

      if (this.isEditing) {
        const index = this.snippets.findIndex(s => s.id === this.form.id)
        if (index !== -1) {
          this.snippets[index] = {
            ...this.form,
            updatedAt: new Date().toLocaleDateString()
          }
          this.selectedSnippet = this.snippets[index]
        }
      } else {
        const newSnippet = {
          ...this.form,
          id: Date.now(),
          updatedAt: new Date().toLocaleDateString()
        }
        this.snippets.unshift(newSnippet)
        this.selectedSnippet = newSnippet
      }

      this.saveToStorage()
      this.dialogVisible = false
      this.$message.success('保存成功')
    },
    deleteSnippet() {
      this.$confirm('确定要删除这个片段吗？', '提示', {
        type: 'warning'
      }).then(() => {
        const index = this.snippets.findIndex(s => s.id === this.selectedSnippet.id)
        if (index !== -1) {
          this.snippets.splice(index, 1)
          this.selectedSnippet = null
          this.saveToStorage()
          this.$message.success('删除成功')
        }
      }).catch(() => {})
    },
    copyCode() {
      navigator.clipboard.writeText(this.selectedSnippet.code).then(() => {
        this.$message.success('已复制到剪贴板')
      })
    }
  }
}
</script>

<style scoped>
.code-snippet-tool {
  padding: 20px;
}

.snippet-list-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}

.snippet-list {
  max-height: 500px;
  overflow-y: auto;
  border: 1px solid #dcdfe6;
  border-radius: 4px;
}

.snippet-item {
  padding: 12px 15px;
  border-bottom: 1px solid #ebeef5;
  cursor: pointer;
  transition: background 0.3s;
}

.snippet-item:hover {
  background: #f5f7fa;
}

.snippet-item.active {
  background: #ecf5ff;
}

.snippet-item:last-child {
  border-bottom: none;
}

.snippet-title {
  font-weight: bold;
  margin-bottom: 5px;
}

.snippet-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.snippet-time {
  font-size: 12px;
  color: #909399;
}

.snippet-detail {
  padding: 10px;
}

.detail-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}

.detail-header h3 {
  margin: 0;
}

.detail-actions {
  display: flex;
  gap: 10px;
}

.detail-info {
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.detail-time {
  font-size: 12px;
  color: #909399;
}

.detail-description {
  color: #606266;
  margin-bottom: 15px;
  padding: 10px;
  background: #f5f7fa;
  border-radius: 4px;
}

.code-area {
  font-family: monospace;
}
</style>
