<template>
  <div class="scientific-calc-tool">
    <el-card>
      <div slot="header">
        <span>科学计算器</span>
      </div>

      <el-row :gutter="20">
        <el-col :span="16">
          <div class="calculator">
            <div class="display">
              <div class="expression">{{ expression || '0' }}</div>
              <div class="result">{{ result }}</div>
            </div>

            <div class="buttons">
              <div class="button-row">
                <el-button @click="inputValue('(')">(</el-button>
                <el-button @click="inputValue(')')">)</el-button>
                <el-button @click="inputValue('Math.PI')">π</el-button>
                <el-button @click="inputValue('Math.E')">e</el-button>
                <el-button type="danger" @click="clear">C</el-button>
                <el-button type="warning" @click="backspace">⌫</el-button>
              </div>

              <div class="button-row">
                <el-button @click="inputValue('Math.sin(')">sin</el-button>
                <el-button @click="inputValue('Math.cos(')">cos</el-button>
                <el-button @click="inputValue('Math.tan(')">tan</el-button>
                <el-button @click="inputValue('Math.log(')">ln</el-button>
                <el-button @click="inputValue('Math.log10(')">log</el-button>
                <el-button @click="inputValue('Math.sqrt(')">√</el-button>
              </div>

              <div class="button-row">
                <el-button @click="inputValue('Math.asin(')">asin</el-button>
                <el-button @click="inputValue('Math.acos(')">acos</el-button>
                <el-button @click="inputValue('Math.atan(')">atan</el-button>
                <el-button @click="inputValue('Math.pow(')">x^y</el-button>
                <el-button @click="inputValue('**2')">x²</el-button>
                <el-button @click="inputValue('**')">^</el-button>
              </div>

              <div class="button-row">
                <el-button @click="inputValue('7')">7</el-button>
                <el-button @click="inputValue('8')">8</el-button>
                <el-button @click="inputValue('9')">9</el-button>
                <el-button @click="inputValue('/')">÷</el-button>
                <el-button @click="inputValue('%')">%</el-button>
                <el-button @click="inputValue('Math.abs(')">|x|</el-button>
              </div>

              <div class="button-row">
                <el-button @click="inputValue('4')">4</el-button>
                <el-button @click="inputValue('5')">5</el-button>
                <el-button @click="inputValue('6')">6</el-button>
                <el-button @click="inputValue('*')">×</el-button>
                <el-button @click="inputValue('1/')">1/x</el-button>
                <el-button @click="inputValue('Math.floor(')">⌊x⌋</el-button>
              </div>

              <div class="button-row">
                <el-button @click="inputValue('1')">1</el-button>
                <el-button @click="inputValue('2')">2</el-button>
                <el-button @click="inputValue('3')">3</el-button>
                <el-button @click="inputValue('-')">−</el-button>
                <el-button @click="inputValue('Math.exp(')">e^x</el-button>
                <el-button @click="inputValue('Math.ceil(')">⌈x⌉</el-button>
              </div>

              <div class="button-row">
                <el-button @click="inputValue('0')">0</el-button>
                <el-button @click="inputValue('.')">.</el-button>
                <el-button @click="inputValue('Math.PI/180*')">deg→rad</el-button>
                <el-button @click="inputValue('+')">+</el-button>
                <el-button type="primary" @click="calculate" class="equal-btn">=</el-button>
              </div>
            </div>
          </div>
        </el-col>

        <el-col :span="8">
          <el-divider>历史记录</el-divider>
          <div class="history">
            <div v-for="(item, index) in history" :key="index" class="history-item" @click="loadHistory(item)">
              <div class="history-expression">{{ item.expression }}</div>
              <div class="history-result">= {{ item.result }}</div>
            </div>
            <el-empty v-if="history.length === 0" description="暂无历史记录" :image-size="80" />
          </div>
          <el-button type="danger" size="small" @click="clearHistory" v-if="history.length > 0">清空历史</el-button>

          <el-divider>常用公式</el-divider>
          <div class="formulas">
            <div v-for="(formula, index) in formulas" :key="index" class="formula-item" @click="useFormula(formula)">
              <span class="formula-name">{{ formula.name }}</span>
              <span class="formula-expr">{{ formula.expression }}</span>
            </div>
          </div>

          <el-divider>角度/弧度</el-divider>
          <el-radio-group v-model="angleMode" size="small">
            <el-radio-button label="deg">角度</el-radio-button>
            <el-radio-button label="rad">弧度</el-radio-button>
          </el-radio-group>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
export default {
  name: 'ScientificCalcTool',
  data() {
    return {
      expression: '',
      result: '0',
      history: [],
      angleMode: 'deg',
      formulas: [
        { name: '勾股定理', expression: 'Math.sqrt(a*a + b*b)' },
        { name: '圆面积', expression: 'Math.PI * r * r' },
        { name: '球体积', expression: '4/3 * Math.PI * r**3' },
        { name: '二次方程', expression: '(-b + Math.sqrt(b*b - 4*a*c)) / (2*a)' },
        { name: '阶乘', expression: 'n!' }
      ]
    }
  },
  methods: {
    inputValue(val) {
      this.expression += val
      this.calculateRealtime()
    },
    calculateRealtime() {
      try {
        if (!this.expression) {
          this.result = '0'
          return
        }
        let expr = this.expression
        if (this.angleMode === 'deg') {
          expr = expr.replace(/Math\.sin\(/g, 'Math.sin(Math.PI/180*')
          expr = expr.replace(/Math\.cos\(/g, 'Math.cos(Math.PI/180*')
          expr = expr.replace(/Math\.tan\(/g, 'Math.tan(Math.PI/180*')
        }
        const result = eval(expr)
        this.result = this.formatNumber(result)
      } catch (e) {
        this.result = '表达式错误'
      }
    },
    calculate() {
      try {
        if (!this.expression) return
        let expr = this.expression
        if (this.angleMode === 'deg') {
          expr = expr.replace(/Math\.sin\(/g, 'Math.sin(Math.PI/180*')
          expr = expr.replace(/Math\.cos\(/g, 'Math.cos(Math.PI/180*')
          expr = expr.replace(/Math\.tan\(/g, 'Math.tan(Math.PI/180*')
        }
        const result = eval(expr)
        this.result = this.formatNumber(result)
        
        this.history.unshift({
          expression: this.expression,
          result: this.result
        })
        if (this.history.length > 20) {
          this.history.pop()
        }
      } catch (e) {
        this.$message.error('计算错误: ' + e.message)
      }
    },
    formatNumber(num) {
      if (typeof num !== 'number') return num
      if (Number.isInteger(num)) return num.toString()
      if (Math.abs(num) < 0.0000001) return '0'
      if (Math.abs(num) > 999999999999) return num.toExponential(6)
      return parseFloat(num.toPrecision(12)).toString()
    },
    clear() {
      this.expression = ''
      this.result = '0'
    },
    backspace() {
      this.expression = this.expression.slice(0, -1)
      this.calculateRealtime()
    },
    loadHistory(item) {
      this.expression = item.expression
      this.result = item.result
    },
    clearHistory() {
      this.history = []
    },
    useFormula(formula) {
      if (formula.name === '阶乘') {
        this.$prompt('请输入一个非负整数', '计算阶乘', {
          confirmButtonText: '计算',
          cancelButtonText: '取消',
          inputPattern: /^\d+$/,
          inputErrorMessage: '请输入非负整数'
        }).then(({ value }) => {
          const n = parseInt(value)
          let result = 1
          for (let i = 2; i <= n; i++) {
            result *= i
          }
          this.expression = `${n}!`
          this.result = this.formatNumber(result)
          this.history.unshift({
            expression: this.expression,
            result: this.result
          })
        })
      } else {
        this.expression = formula.expression
      }
    }
  }
}
</script>

<style scoped>
.scientific-calc-tool {
  padding: 20px;
}

.calculator {
  background: #f5f7fa;
  border-radius: 12px;
  padding: 20px;
}

.display {
  background: white;
  border-radius: 8px;
  padding: 15px;
  margin-bottom: 15px;
  text-align: right;
}

.expression {
  font-size: 16px;
  color: #909399;
  min-height: 24px;
  word-break: break-all;
}

.result {
  font-size: 32px;
  font-weight: bold;
  color: #303133;
  margin-top: 5px;
}

.buttons {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.button-row {
  display: flex;
  gap: 8px;
}

.button-row .el-button {
  flex: 1;
  height: 50px;
  font-size: 16px;
  font-weight: 500;
}

.equal-btn {
  flex: 2 !important;
}

.history {
  max-height: 200px;
  overflow-y: auto;
}

.history-item {
  padding: 10px;
  background: #f5f7fa;
  border-radius: 6px;
  margin-bottom: 8px;
  cursor: pointer;
  transition: all 0.3s;
}

.history-item:hover {
  background: #e6f7ff;
}

.history-expression {
  font-size: 12px;
  color: #909399;
}

.history-result {
  font-size: 16px;
  font-weight: bold;
  color: #303133;
}

.formulas {
  max-height: 200px;
  overflow-y: auto;
}

.formula-item {
  display: flex;
  justify-content: space-between;
  padding: 8px 12px;
  background: #f5f7fa;
  border-radius: 6px;
  margin-bottom: 6px;
  cursor: pointer;
  transition: all 0.3s;
}

.formula-item:hover {
  background: #e6f7ff;
}

.formula-name {
  font-weight: 500;
  color: #409eff;
}

.formula-expr {
  font-family: monospace;
  font-size: 12px;
  color: #909399;
}
</style>
