        { pattern: '[0-9]', description: '匹配数字', example: '0, 5, 9' },
        { pattern: '[a-zA-Z0-9]', description: '匹配字母和数字', example: 'a1, B2, x9' },
        { pattern: '\\d', description: '匹配数字', example: '0, 1, 9' },
        { pattern: '\\D', description: '匹配非数字', example: 'a, B, !' },
        { pattern: '\\w', description: '匹配单词字符', example: 'a, 1, _' },
        { pattern: '\\W', description: '匹配非单词字符', example: '!, @, #' },
        { pattern: '\\s', description: '匹配空白字符', example: '空格, 制表符, 换行' },
        { pattern: '\\S', description: '匹配非空白字符', example: 'a, 1, !' },
