        { pattern: '?', description: '匹配0次或1次', example: 'a? 匹配空, a' },
        { pattern: '{n}', description: '匹配n次', example: 'a{3} 匹配 aaa' },
        { pattern: '{n,m}', description: '匹配n到m次', example: 'a{2,4} 匹配 aa, aaa, aaaa' },
        { pattern: '.', description: '匹配任意字符', example: 'a.b 匹配 aab, a1b, a!b' },
        { pattern: '[abc]', description: '匹配字符集中的任意一个', example: '[abc] 匹配 a, b, c' },
        { pattern: '[^abc]', description: '匹配不在字符集中的字符', example: '[^abc] 匹配 d, e, f' },
        { pattern: '(abc)', description: '分组', example: '(abc) 匹配 abc' },
        { pattern: 'a|b', description: '匹配a或b', example: 'a|b 匹配 a, b' },
        { pattern: '\\b', description: '匹配单词边界', example: '\\babc\\b 匹配 abc' },
        { pattern: '\\B', description: '匹配非单词边界', example: '\\Babc\\B 匹配 xabcx' },
        { pattern: '\\d{3}-\\d{2}-\\d{4}', description: '匹配日期格式', example: '2024-01-01' },
        { pattern: '\\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Z|a-z]{2,}\\b', description: '匹配邮箱', example: 'user@example.com' },
        { pattern: '^https?:\\/\\/[\\S]+$', description: '匹配URL', example: 'https://example.com' },
        { pattern: '^1[3-9]\\d{9}$|^14[579]\\d{8}$', description: '匹配手机号', example: '13800138000' },
        { pattern: '^[1-9]\\d{5}$', description: '匹配邮编', example: '100000' },
        { pattern: '^[0-9a-fA-F]{32}$', description: '匹配MD5', example: '5d41402abc4b2a76b9719d911017c592' },
        { pattern: '^[0-9a-fA-F]{40}$', description: '匹配SHA1', example: 'da39a3ee5e6b4b0d3255bfef95601890afd80709' }
      ],
      gitCommands: [
        { command: 'git init', description: '初始化仓库', example: 'git init' },
        { command: 'git clone', description: '克隆远程仓库', example: 'git clone https://github.com/user/repo.git' },
        { command: 'git add', description: '添加文件到暂存区', example: 'git add . 或 git add file.txt' },
        { command: 'git commit', description: '提交更改', example: 'git commit -m "提交信息"' },
        { command: 'git push', description: '推送到远程仓库', example: 'git push origin main' },
        { command: 'git pull', description: '拉取远程更改', example: 'git pull origin main' },
        { command: 'git status', description: '查看工作区状态', example: 'git status' },
        { command: 'git log', description: '查看提交历史', example: 'git log --oneline' },
        { command: 'git branch', description: '查看/创建分支', example: 'git branch 或 git branch feature' },
        { command: 'git checkout', description: '切换分支', example: 'git checkout main' },
        { command: 'git merge', description: '合并分支', example: 'git merge feature' },
        { command: 'git diff', description: '查看差异', example: 'git diff 或 git diff file.txt' },
