        { command: 'git revert', description: '撤销提交', example: 'git revert HEAD' },
        { command: 'git stash', description: '暂存更改', example: 'git save 或 git stash pop' },
        { command: 'git remote', description: '管理远程仓库', example: 'git remote add origin https://github.com/user/repo.git' },
        { command: 'git fetch', description: '获取远程更新', example: 'git fetch origin' },
        { command: 'git tag', description: '创建标签', example: 'git tag v1.0.0' },
        { command: 'git show', description: '查看提交详情', example: 'git show HEAD' },
        { command: 'git rm', description: '删除文件', example: 'git rm file.txt' },
        { command: 'git mv', description: '移动/重命名文件', example: 'git mv old.txt new.txt' },
        { command: 'git rebase', description: '变基', example: 'git rebase main' },
        { command: 'git cherry-pick', description: '挑选提交', example: 'git cherry-pick abc123' },
        { command: 'git blame', description: '查看文件修改历史', example: 'git blame file.txt' },
        { command: 'git config', description: '配置Git', example: 'git config user.name "Your Name"' },
        { command: 'git clean', description: '清理未跟踪文件', example: 'git clean -fd' },
        { command: 'git bisect', description: '二分查找问题', example: 'git bisect start' },
        { command: 'git submodule', description: '管理子模块', example: 'git submodule add https://github.com/user/repo.git' }
      ]
    }
  },
  computed: {
    filteredHttpCodes() {
      if (!this.httpSearch) return this.httpCodes
      const search = this.httpSearch.toLowerCase()
      return this.httpCodes.filter(item => 
        item.code.includes(search) ||
        item.name.toLowerCase().includes(search) ||
        item.description.toLowerCase().includes(search)
      )
    },
    filteredColors() {
      if (!this.colorSearch) return this.colors
      const search = this.colorSearch.toLowerCase()
      return this.colors.filter(item => 
        item.name.toLowerCase().includes(search) ||
        item.hex.toLowerCase().includes(search) ||
        item.rgb.toLowerCase().includes(search)
      )
    },
    filteredAscii() {
      if (!this.asciiSearch) return this.ascii
      const search = this.asciiSearch.toLowerCase()
      return this.ascii.filter(item => 
        item.dec.toString().includes(search) ||
        item.hex.toLowerCase().includes(search) ||
        item.char.toLowerCase().includes(search) ||
        item.description.toLowerCase().includes(search)
      )
    },
    filteredMimeTypes() {
      if (!this.mimeSearch) return this.mimeTypes
      const search = this.mimeSearch.toLowerCase()
      return this.mimeTypes.filter(item => 
        item.extension.toLowerCase().includes(search) ||
        item.mime.toLowerCase().includes(search)
      )
    },
    filteredRegex() {
      if (!this.regexSearch) return this.regexPatterns
      const search = this.regexSearch.toLowerCase()
      return this.regexPatterns.filter(item => 
        item.pattern.toLowerCase().includes(search) ||
        item.description.toLowerCase().includes(search) ||
        item.example.toLowerCase().includes(search)
      )
    },
    filteredGitCommands() {
      if (!this.gitSearch) return this.gitCommands
      const search = this.gitSearch.toLowerCase()
      return this.gitCommands.filter(item => 
        item.command.toLowerCase().includes(search) ||
        item.description.toLowerCase().includes(search) ||
        item.example.toLowerCase().includes(search)
      )
    }
  },
  methods: {
    selectColor(row) {
      this.selectedColor = row.hex
    }
  }
}
