/**
 * 通用搜索：支持中英混合、无空格匹配、多 token AND 匹配
 * @param {string} keyword 用户输入
 * @param {Array} tools 待搜索的工具列表
 * @param {Object} [opts]
 * @param {number} [opts.limit] 最大结果数
 * @param {boolean} [opts.includeKeywords] 是否参与 keywords/desc 字段（默认 true）
 */
export function searchTools(keyword, tools, opts = {}) {
  const { limit = 12, includeKeywords = true } = opts
  const raw = (keyword || '').trim()
  if (!raw) return []
  const tokens = raw.toLowerCase().split(/[\s,，/、]+/).filter(Boolean)
  const compact = raw.toLowerCase().replace(/\s+/g, '')
  return tools.filter(tool => {
    const fields = includeKeywords
      ? [tool.name, tool.desc, tool.category, tool.keywords || '']
      : [tool.name, tool.category]
    const haystack = fields.join(' ').toLowerCase()
    const haystackCompact = haystack.replace(/\s+/g, '')
    if (compact && (haystack.includes(compact) || haystackCompact.includes(compact))) {
      return true
    }
    return tokens.every(t => haystack.includes(t) || haystackCompact.includes(t))
  }).slice(0, limit)
}
